cat > /mnt/user-data/outputs/trends_data.js << 'ENDOFFILE'
export const TRENDS = [
  // ── FOOD & DRINK ─────────────────────────────────────────────
  { id:1, nombre:"Dark Kitchen con Suscripción", emoji:"🍱", sector:"Food & Drink", potencial:"Alta", dificultad:"Fácil", resumen:"Cocinas fantasma que venden suscripciones semanales de comida sin tener local a pie de calle.", por_que:"Tras el COVID, el mercado de dark kitchens en EE.UU. alcanzó 67.000M$ en 2023 (Statista). Empresas como Kitchen United y CloudKitchens de Travis Kalanick han captado más de 1.000M$ en inversión. El modelo de suscripción añade ingresos recurrentes predecibles: startups como Trifecta Nutrition facturan 100M$ anuales solo con suscripciones de meal prep. El coste de apertura es 10 veces menor que un restaurante tradicional.", como_aplicar:"España tiene el tercer mayor mercado de delivery de Europa con 2.300M€ anuales (Statista 2024), pero solo el 12% opera como dark kitchen. Las ciudades de entre 100.000 y 500.000 habitantes (Zaragoza, Valladolid, Murcia) están completamente desatendidas. Un modelo de suscripción mensual de 150-250€ con 4 menús semanales y nichos como 'mediterráneo saludable' o 'alto en proteína' tiene diferenciación clara frente a Glovo y Uber Eats.", riesgos:["Dependencia de plataformas de delivery que cobran 25-30% de comisión","Rotación alta de clientes si la calidad varía entre semanas","Regulación sanitaria de cocinas compartidas varía por comunidad autónoma"], pasos:["Alquilar espacio en cloud kitchen (Cuyna o Kitchen Club en España, desde 800€/mes)","Validar demanda con 30 suscriptores piloto antes de invertir en producción","Construir canal directo por WhatsApp Business para evitar comisiones de plataformas","Automatizar logística con Shopify + Stuart o Borzo para reparto propio"] },

  { id:2, nombre:"Bares de Zumo en Frío (Cold Press)", emoji:"🥤", sector:"Food & Drink", potencial:"Alta", dificultad:"Fácil", resumen:"Tiendas especializadas en zumos prensados en frío, shots de jengibre y batidos funcionales sin aditivos.", por_que:"Pressed Juicery (EE.UU.) factura más de 100M$ con más de 100 locales. El mercado global de cold press juice alcanzará 1.100M$ en 2025 (Grand View Research). El ticket medio por cliente es de 12-18€ con margen bruto del 60-70%, muy superior a la cafetería tradicional. El consumidor fitness paga por conveniencia y por la percepción de salud.", como_aplicar:"En España el concepto existe en Barcelona y Madrid pero de forma muy fragmentada y sin marca sólida. El 63% de españoles declara querer mejorar su alimentación (CIS 2024). Una cadena de 3-5 locales bien ubicados cerca de gimnasios, mercados gourmet o zonas de oficinas en ciudades medianas puede capturar un mercado sin competencia directa.", riesgos:["Producto perecedero con vida útil de 3-5 días que obliga a producción diaria","Prensadora hidráulica de calidad cuesta entre 15.000-30.000€","Ventas caen hasta un 40% en meses de invierno si no se diversifica la oferta"], pasos:["Empezar vendiendo online con entrega a domicilio para validar demanda sin alquiler de local","Crear suscripción semanal de 5 zumos a 45€/semana para ingresos recurrentes","Ubicar primer local en zona con alto tráfico fitness (cerca de gimnasio + supermercado ecológico)","Añadir línea de shots (jengibre, cúrcuma, wheatgrass) con margen del 80%"] },

  { id:3, nombre:"Meal Prep Delivery Fitness", emoji:"💪", sector:"Food & Drink", potencial:"Alta", dificultad:"Moderada", resumen:"Servicio de preparación y entrega de comidas semanales con macros calculados por nutricionistas, listas para calentar.", por_que:"Factor75 (EE.UU.) fue adquirida por HelloFresh por 277M$. Trifecta Nutrition factura 100M$+ anuales. El mercado de meal prep en EE.UU. crece al 12% anual y alcanzará 20.000M$ en 2027. El cliente fitness busca principalmente tiempo y conveniencia: el 78% de usuarios de gimnasio declara que 'comer bien' es su mayor dificultad (encuesta MyFitnessPal 2023).", como_aplicar:"España tiene 11,5 millones de personas que van al gimnasio (IHRSA 2024) y un mercado de nutrición deportiva de 850M€. Apenas existen servicios de meal prep serios con macros certificados por nutricionistas. Un servicio a 7-10€ por comida con plan de 5 días (35-50€/semana) orientado a ganancia muscular, pérdida de grasa o rendimiento deportivo tiene demanda inmediata en cualquier ciudad con más de 100.000 habitantes.", riesgos:["Logística de cadena de frío requiere vehículos refrigerados o acuerdo con empresa logística especializada","Margen se comprime por debajo del 30% si el volumen de clientes es inferior a 200 suscripciones semanales","Alta rotación si el menú no varía suficientemente semana a semana"], pasos:["Contratar dietista-nutricionista colegiado para diseñar y firmar los planes nutricionales (obligatorio legalmente)","Comenzar con reparto propio solo en radio de 20km para controlar calidad de entrega","Lanzar 3 planes diferenciados: Volumen, Definición y Alto Rendimiento","Usar TikTok e Instagram con contenido de 'preparación de la semana' para captación orgánica"] },

  { id:4, nombre:"Ghost Bakery (Panadería Fantasma)", emoji:"🥐", sector:"Food & Drink", potencial:"Alta", dificultad:"Fácil", resumen:"Panadería artesanal sin local físico que vende por pedido anticipado en Instagram o WhatsApp, con recogida o delivery.", por_que:"En EE.UU. las ghost bakeries en Instagram generan entre 5.000$ y 50.000$/mes sin pagar alquiler. El modelo de 'preventa semanal' elimina el desperdicio completamente. Microemprendedoras como Hannah Kaminsky (100K seguidores, 30K$/mes) han demostrado que el contenido visual de repostería convierte mejor que cualquier otro sector en Instagram: tasa de conversión del 8-12% vs 2% de media.", como_aplicar:"El mercado español de pan artesanal y bollería premium creció un 23% en 2023. Los consumidores pagan entre 5-15€ por una pieza de pan de masa madre o un croissant de mantequilla francesa. Una ghost bakery especializada en un solo producto (masa madre, croissants, babkas, cinnamon rolls) en cualquier ciudad española puede generar 3.000-8.000€/mes con costes fijos casi nulos.", riesgos:["Normativa sanitaria para venta alimentaria desde obrador doméstico varía por comunidad autónoma","Escalar la producción más allá de 200 piezas/semana requiere obrador profesional (800-1.500€/mes)","Dependencia total de Instagram: cambios en algoritmo pueden hundir las ventas"], pasos:["Verificar con el Ayuntamiento los requisitos para venta alimentaria artesanal en tu municipio","Crear perfil Instagram con identidad visual muy cuidada y publicar 2-3 semanas antes de abrir pedidos","Sistema de pedidos por Google Forms + pago por Bizum o Stripe","Lanzar con un único producto y dominarlo antes de ampliar catálogo"] },

  { id:5, nombre:"Cafeterías de Especialidad con Membresía", emoji:"☕", sector:"Food & Drink", potencial:"Media", dificultad:"Fácil", resumen:"Cafeterías de café de especialidad que ofrecen membresía mensual para café diario ilimitado o con descuento.", por_que:"Panera Bread lanzó su Coffee Club a 10.99$/mes y añadió 40M$ de ingresos recurrentes en el primer año, con 28 millones de descargas de su app. Blank Street Coffee (NYC) con este modelo captó 67M$ en inversión. La membresía sube el LTV (valor de vida del cliente) de 200€ a 2.000€+ anuales y convierte compradores ocasionales en clientes diarios.", como_aplicar:"España consume 4,5kg de café per cápita al año (ICO 2024), el cuarto mayor consumidor europeo. El mercado de café de especialidad crece al 15% anual pero sigue siendo nicho en ciudades medianas. Una membresía a 25-35€/mes con café de filtro, cortado o flat white ilimitados en zona de oficinas crea fidelidad imposible de igualar con descuentos puntuales.", riesgos:["Margen se reduce drásticamente si los socios consumen más de 2 cafés diarios","Requiere masa crítica mínima de 80-100 socios para ser rentable","Competencia de cadenas internacionales con más recursos de marketing"], pasos:["Calcular precio de membresía basado en consumo medio real de tus clientes actuales","Lanzar con precio fundador a los primeros 50 socios (ej: 19€/mes el primer año)","App o tarjeta NFC para registro de consumo (Gloriafood o Square)","Ofrecer beneficios exclusivos: catas mensuales, descuento en bolsas de café para llevar"] },

  { id:6, nombre:"Restaurantes Build Your Own Bowl", emoji:"🌯", sector:"Food & Drink", potencial:"Alta", dificultad:"Moderada", resumen:"Restaurantes de formato rápido donde el cliente construye su plato eligiendo base, proteína, toppings y salsa.", por_que:"Chipotle Mexican Grill factura 9.800M$ anuales con 3.500 locales. Sweetgreen vale 1.800M$ en bolsa. Cava Group (bowls mediterráneos) creció un 28% en 2023 y tiene 300+ locales. El formato 'build your own' genera ticket medio de 12-16€ con tiempos de servicio de 3-4 minutos, permitiendo 200-300 clientes en hora punta. El margen bruto es del 65-70%.", como_aplicar:"En España el formato existe en versión básica (Bacoa, Honest Greens) pero sin la operativa optimizada ni el branding de las cadenas americanas. Un concepto de 'bowl mediterráneo' con ingredientes 100% españoles (hummus, falafel, pollo al ajillo, pisto, queso manchego) tiene propuesta diferenciadora única y aprovecha la tendencia saludable sin renunciar a los sabores locales.", riesgos:["Operativa compleja con 20-30 ingredientes frescos que requiere formación intensa del equipo","Necesita volumen mínimo de 150 comidas/día para amortizar costes fijos del local","La línea de preparación visible exige limpieza impecable durante todo el servicio"], pasos:["Definir carta de máximo 5 bases, 5 proteínas, 10 toppings y 6 salsas (simplicidad operativa)","Abrir primero como dark kitchen para validar las combinaciones más populares","Ubicación ideal: radio de 300m de zona de oficinas con más de 500 trabajadores","Implementar app de pedido anticipado desde día 1 para gestionar picos de demanda"] },

  { id:7, nombre:"Supermercados de Productos Internacionales", emoji:"🌍", sector:"Food & Drink", potencial:"Alta", dificultad:"Fácil", resumen:"Tiendas especializadas en productos alimentarios auténticos de Asia, Latinoamérica, Oriente Medio y África.", por_que:"H Mart (cadena coreana en EE.UU.) tiene 100+ locales y factura 1.000M$+ anuales. 99 Ranch Market (productos asiáticos) factura 500M$. El 23% de la población de EE.UU. busca activamente ingredientes de su cultura de origen y paga un premium del 30-40% por autenticidad. El auge del contenido de cocina étnica en TikTok ha creado demanda masiva entre consumidores no inmigrantes.", como_aplicar:"España tiene 5,6 millones de extranjeros residentes (INE 2024) y una creciente obsesión culinaria por cocinas asiáticas, mexicanas y árabes. El 67% de españoles declara cocinar platos de otras culturas regularmente (encuesta Mercadona 2024). Una tienda especializada en una región concreta (Asia Oriental, Latinoamérica, Sur de Asia) con productos auténticos imposibles de encontrar en Mercadona o El Corte Inglés tiene clientela fiel y ticket medio de 35-60€.", riesgos:["Importación de productos requiere gestión aduanera y certificados sanitarios europeos","Rotación de stock compleja con productos perecederos de difícil aprovisionamiento","Necesitas conocimiento profundo del nicho cultural al que sirves para no perder credibilidad"], pasos:["Elegir una sola región cultural para especializarse completamente","Conectar con importadores mayoristas especializados (Makro tiene línea asiática, o importadores directos en Mercabarna)","Local de 100-200m² en barrio con presencia de la comunidad objetivo","Crear contenido en redes sobre recetas con tus productos para atraer clientes no inmigrantes"] },

  // ── FITNESS & SALUD ──────────────────────────────────────────
  { id:8, nombre:"Clínicas de Salud Mental Online", emoji:"🧠", sector:"Fitness & Salud", potencial:"Alta", dificultad:"Moderada", resumen:"Plataformas que conectan psicólogos colegiados con pacientes por videollamada con modelos de suscripción o pago por sesión.", por_que:"BetterHelp (EE.UU.) factura 1.100M$ anuales con 30.000 terapeutas y 4 millones de clientes. Talkspace vale 300M$. El mercado global de salud mental digital alcanzará 17.500M$ en 2030 (Allied Market Research). La pandemia normalizó la terapia online: el 65% de pacientes prefiere el formato digital por flexibilidad horaria y ausencia de estigma social.", como_aplicar:"España tiene una de las tasas más altas de ansiedad y depresión de Europa: 6,7 millones de personas afectadas (Ministerio de Sanidad 2024) con lista de espera media de 4-6 meses en la sanidad pública. El precio privado presencial (70-100€/sesión) crea una barrera económica que el formato online puede reducir a 40-60€. Plataformas como Ifeel o Psicólogos Online existen pero hay espacio para propuestas especializadas por nicho (burnout laboral, maternidad, adolescentes).", riesgos:["Solo pueden ofrecer terapia psicólogos con número de colegiado: proceso de reclutamiento exigente","La LOPD aplicada a datos de salud mental es especialmente estricta y requiere asesoramiento legal","Retención baja si el match terapeuta-paciente no funciona en las primeras 3 sesiones"], pasos:["Definir nicho específico: no 'psicología general' sino 'burnout para directivos' o 'ansiedad en madres primerizas'","Plataforma técnica mínima: Calendly + Stripe + Zoom o Whereby (coste <200€/mes)","Reclutamiento inicial de 10-15 psicólogos autónomos con 50/50 de ingresos","Certificación ENS (Esquema Nacional de Seguridad) para datos de salud desde el día 1"] },

  { id:9, nombre:"Estudios de Fitness Boutique", emoji:"🏋️", sector:"Fitness & Salud", potencial:"Alta", dificultad:"Moderada", resumen:"Pequeños estudios especializados en un solo formato (HIIT, pilates reformer, boxing, yoga) con reserva por app y comunidad.", por_que:"SoulCycle (spinning) fue valorada en 900M$. Orangetheory Fitness tiene 1.500 locales en 23 países y factura 1.200M$. El modelo boutique cobra 25-40$/clase vs 30-50$/mes de gym tradicional, generando 10x más ingresos por m². La tasa de retención es del 70-80% vs 40% de gimnasios convencionales gracias al efecto comunidad.", como_aplicar:"España tiene 11.500 gimnasios (IHRSA) pero menos del 3% son estudios boutique especializados. El gimnasio tradicional está en declive (-8% en 2023) mientras los boutique crecen al +22%. Un estudio de pilates reformer (la disciplina que más crece en España: +34% en 2023) con 12-16 reformers y clases de 8-10 personas a 25-35€/clase puede generar 15.000-25.000€/mes en un local de 150m².", riesgos:["Inversión inicial en equipamiento específico: reformers de pilates cuestan 2.000-4.000€ cada uno","Rentabilidad depende de ocupación mínima del 75%: necesitas base de 150-200 clientes activos","El instructor principal es el principal activo y riesgo: si se va, se lleva a los clientes"], pasos:["Elegir UN solo formato y dominarlo completamente antes de diversificar","Mindbody o Glofox para gestión de reservas y pagos (60-100€/mes)","Lanzar membresías fundadoras a precio reducido para asegurar base mínima antes de abrir","Contratar instructor con comunidad propia en Instagram como cofundador con participación"] },

  { id:10, nombre:"Clínicas de Recuperación Deportiva", emoji:"🧊", sector:"Fitness & Salud", potencial:"Alta", dificultad:"Moderada", resumen:"Centros de recuperación con crioterapia, baños de hielo, sauna finlandesa, compresión neumática y masaje deportivo.", por_que:"Restore Hyper Wellness (EE.UU.) tiene 200+ locales, factura 150M$ y está en proceso de IPO. El mercado de wellness recuperación alcanzará 7.000M$ en 2025. Atletas como LeBron James y Cristiano Ronaldo han popularizado la crioterapia: el deportista amateur quiere acceso a las mismas herramientas. Ticket medio 60-120€/sesión con margen del 60%.", como_aplicar:"En España hay menos de 50 centros de crioterapia y están concentrados en Madrid y Barcelona. El boom del running (6,5 millones de corredores habituales en España), ciclismo y triatlón genera demanda enorme de recuperación entre deportistas amateur dispuestos a pagar. Un centro en ciudad universitaria o cerca de zona deportiva con membresía de 80-150€/mes tiene diferenciación muy clara.", riesgos:["Cámara de crioterapia whole-body cuesta 50.000-80.000€ y requiere mantenimiento especializado","Necesitas seguro de responsabilidad civil específico para actividades de criobienestar","Mercado en fase de educación: el 70% de potenciales clientes no conoce los beneficios"], pasos:["Empezar solo con baños de hielo (ice bath, inversión 2.000-5.000€) y sauna finlandesa para validar demanda","Añadir crioterapia localizada (no whole-body) como segundo paso: equipos desde 8.000€","Ubicarse junto a un gimnasio o club deportivo con base de clientes ya educada","Crear contenido educativo: 'protocolo de recuperación del atleta amateur' para posicionamiento orgánico"] },

  { id:11, nombre:"Academias de Padel Indoor Premium", emoji:"🎾", sector:"Fitness & Salud", potencial:"Alta", dificultad:"Difícil", resumen:"Centros de padel cubiertos con entrenamiento personalizado con IA, torneos privados y modelo de membresía premium.", por_que:"El padel es el deporte de mayor crecimiento mundial: 25 millones de jugadores en España (FEP 2024), crecimiento del 80% en 5 años. En EE.UU., Padel Haus (NYC) cobra 120$/mes de membresía y tiene lista de espera de 6 meses. Topgolf (modelo similar para golf) fue valorado en 2.000M$. Las instalaciones de padel en España son mayoritariamente básicas y sin servicios de valor añadido.", como_aplicar:"El padelista español promedio gasta 1.200€/año en el deporte pero en instalaciones de baja calidad. Un centro indoor premium con app de análisis de juego por IA (ya existen soluciones como PlaySight), academia para todos los niveles, restaurante saludable y eventos sociales puede cobrar membresías de 150-300€/mes en ciudades medianas con 0 competencia directa.", riesgos:["Inversión mínima de 400.000-800.000€ para 4-6 pistas cubiertas con calidades premium","Ciclo de venta de membresías lento: mínimo 6-12 meses para alcanzar breakeven","Riesgo de oversupply en grandes ciudades donde ya hay saturación de pistas de padel"], pasos:["Buscar nave industrial de 2.000-3.000m² en ciudad de 80.000-300.000 habitantes sin competencia premium","Modelo de financiación: preventa de 200 membresías fundadoras antes de construir para validar demanda real","Tecnología de análisis de juego como diferenciador principal (PlaySight o Slinger Bag)","Asociarse con entrenadores con seguidores en redes como cofundadores"] },

  { id:12, nombre:"Coaching de Salud y Hábitos por App", emoji:"📱", sector:"Fitness & Salud", potencial:"Alta", dificultad:"Fácil", resumen:"Programa de cambio de hábitos con coach personal por app que integra nutrición, ejercicio, sueño y gestión del estrés.", por_que:"Noom (EE.UU.) tiene 4,5 millones de suscriptores y factura 400M$+ anuales a 60$/mes. Future (coaching personalizado por app) fue valorada en 1.000M$. El 73% de personas que intentan cambiar hábitos fracasan sin acompañamiento. El coaching digital personalizado tiene una tasa de éxito 3 veces superior a los programas genéricos (Journal of Medical Internet Research 2023).", como_aplicar:"España tiene el segundo mayor mercado de apps de salud de Europa con 8,3 millones de usuarios activos. Sin embargo, la oferta de coaching real (no bots) con seguimiento humano es escasa. Un servicio de coaching a 79-129€/mes con coach humano asignado, check-ins semanales y metodología de 12 semanas basada en evidencia tiene diferenciación clara frente a apps genéricas como Freeletics o Nike Training.", riesgos:["Escalar requiere contratar más coaches, lo que comprime márgenes por debajo del 30% con menos de 500 clientes","Tasa de abandono alta en semanas 3-6 si no hay resultados visibles rápidos","Credenciales del coach son determinantes: el cliente exige titulación oficial"], pasos:["Empezar tú mismo como coach con los primeros 10 clientes beta a precio reducido para afinar metodología","Crear programa de 12 semanas con hitos medibles y celebraciones cada semana","Escalar contratando coaches con tu metodología probada cuando tengas 50+ clientes satisfechos","Canal de captación principal: grupos de Facebook de madres, corredores, gente con diabetes tipo 2"] },

  { id:13, nombre:"Test Genéticos de Nutrición y Deporte", emoji:"🧬", sector:"Fitness & Salud", potencial:"Media", dificultad:"Moderada", resumen:"Kits de ADN que analizan predisposición genética para personalizar dieta, suplementación y plan de entrenamiento.", por_que:"23andMe fue valorada en 3.500M$ en su IPO. DNAfit (UK) vende 50.000+ kits anuales a 149-299£. El mercado de genómica de consumo alcanzará 4.500M$ en 2026. El consumidor fitness está dispuesto a pagar por personalización extrema: el 84% de usuarios de DNAfit declara haber cambiado su dieta basándose en los resultados (informe interno 2023).", como_aplicar:"En España el mercado existe pero sin actores locales fuertes. Tellmegen (española) ha vendido más de 100.000 kits pero no tiene línea específica de nutrición deportiva. Un producto diferenciado con análisis de ADN + informe en español + consulta online con nutricionista deportivo incluida + plan de suplementación personalizada puede justificar un precio de 199-399€ con márgenes del 60%.", riesgos:["RGPD aplicado a datos genéticos es el marco legal más exigente de Europa: necesitas DPO desde el día 1","Dependencia de laboratorio certificado: coste por muestra analizada de 30-60€","Credibilidad científica difícil de comunicar: mercado susceptible a pseudociencia y regulación de la AESAN"], pasos:["Acuerdo con laboratorio europeo certificado ISO 15189 para análisis genético","Equipo médico-científico para diseñar los algoritmos de recomendación nutricional","Paquete completo: kit + análisis + informe personalizado + consulta 30 min con nutricionista","Canal inicial: clínicas de nutrición y médicos deportivos como prescriptores"] },

  // ── TECH ─────────────────────────────────────────────────────
  { id:14, nombre:"SaaS de Gestión para Clínicas Pequeñas", emoji:"🏥", sector:"Tech", potencial:"Alta", dificultad:"Moderada", resumen:"Software todo-en-uno para clínicas de fisioterapia, psicología o estética: agenda, cobros, historia clínica e informes automáticos.", por_que:"Jane App (Canadá) factura 50M$+ anuales sirviendo a 75.000 clínicas. SimplePractice (EE.UU.) tiene 200.000 terapeutas y fue valorada en 900M$. El 78% de clínicas pequeñas usa Excel, papel o WhatsApp para gestionar citas (encuesta Booking 2023). El mercado de software sanitario para PYMEs crecerá al 14% anual hasta 2030.", como_aplicar:"España tiene 45.000 clínicas de fisioterapia, 25.000 psicólogos privados y 80.000 centros de estética, la mayoría sin software de gestión adecuado. Un SaaS a 49-99€/mes con soporte telefónico en español (diferenciador clave vs competencia internacional), integración con la Seguridad Social y facturación automática tiene un mercado total direccionable de 500M€ anuales.", riesgos:["Cumplimiento de la LOPD en datos de salud requiere auditoría legal costosa antes del lanzamiento","Ciclo de venta largo: el profesional sanitario es conservador y tarda 3-6 meses en decidir cambiar de software","Integración con software de facturación español (Holded, Contasimple) es obligatoria para competir"], pasos:["Elegir UN solo tipo de clínica para el MVP: fisioterapia tiene mayor urgencia de digitalización","Entrevistar a 30 fisioterapeutas para identificar los 3 mayores dolores diarios","MVP en 3 meses con solo 4 funciones: agenda, cobros, historia clínica y recordatorios SMS","Precio de lanzamiento: 29€/mes los primeros 6 meses para los primeros 100 clientes"] },

  { id:15, nombre:"IA para Gestión de Redes de PYMEs", emoji:"📲", sector:"Tech", potencial:"Alta", dificultad:"Moderada", resumen:"Herramienta que genera, programa y analiza contenido para redes sociales de pequeños negocios con IA entrenada por sector.", por_que:"Buffer fue valorada en 60M$. Hootsuite en 900M$. Pero ambas son genéricas. Vista Social y Publer especializados en PYMEs crecen al 40% anual. La IA generativa ha reducido el coste de producción de contenido un 80%: ahora es posible crear una herramienta vertical para un sector específico con ventaja competitiva real sobre las genéricas.", como_aplicar:"El 71% de PYMEs españolas tiene redes sociales desatendidas (IAB Spain 2024). Una herramienta específica para restaurantes (entiende términos de carta, genera posts de platos del día, responde reseñas de Google) o para clínicas (cumplimiento LOPD en contenido) a 29-49€/mes es 10 veces más útil que una genérica. El canal de venta a través de distribuidores (agencias de marketing local) puede dar escala rápida.", riesgos:["Mercado muy competido a nivel global con actores como Buffer, Later, Metricool con millones en marketing","Diferenciación vertical se erosiona cuando las genéricas añaden funciones similares en 12-18 meses","Las PYMEs tienen presupuesto tecnológico muy limitado: tasa de churn alta si no ven ROI inmediato"], pasos:["Elegir un único sector vertical con lenguaje específico: restaurantes, inmobiliarias o clínicas de estética","Construir base de datos de contenido de alto rendimiento del sector para entrenar el modelo","Integración nativa con Instagram, Facebook, Google Business y TikTok desde día 1","Canal de ventas: alianza con asociaciones empresariales sectoriales para acceso masivo a base de clientes"] },

  { id:16, nombre:"Marketplace de Servicios Hiperlocales", emoji:"🗺️", sector:"Tech", potencial:"Alta", dificultad:"Difícil", resumen:"App que conecta vecinos con profesionales verificados del barrio: fontaneros, electricistas, canguros, clases particulares.", por_que:"Thumbtack (EE.UU.) vale 3.200M$ con 10 millones de proyectos anuales. Angi (antes HomeAdvisor) factura 1.800M$. TaskRabbit (adquirida por IKEA) opera en 75 ciudades. El mercado de servicios del hogar en EE.UU. alcanza 600.000M$ anuales y está altamente fragmentado. La confianza basada en reviews de vecinos reales aumenta la tasa de conversión en un 340% vs plataformas genéricas.", como_aplicar:"Habitissimo (española) procesa 2 millones de solicitudes anuales pero cobra comisiones del 15-25% y tiene escasa verificación de calidad. Una plataforma hiperlocal con verificación de identidad biométrica, reviews verificadas por trabajo completado y precio fijo por categoría puede capturar el mercado de ciudades medianas donde la confianza personal es más valiosa que el precio.", riesgos:["Efecto de red bilateral: necesitas simultáneamente oferta (profesionales) y demanda (clientes) por zona geográfica","Lanzamiento ciudad por ciudad es lento y costoso: mínimo 6-12 meses por ciudad","Fraude en reviews y calidad de profesionales requiere equipo de confianza y verificación dedicado"], pasos:["Lanzar en un único barrio de 20.000 habitantes antes de escalar: Chamberí (Madrid), Gràcia (Barcelona)","Verificar manualmente y entrevistar a los primeros 50 profesionales para establecer estándares de calidad","Comisión del 10-15% por trabajo completado (cobrar solo al cerrar el trabajo, no al hacer match)","Campaña puerta a puerta en el barrio con folletos y descuentos de lanzamiento para captación inicial"] },

  { id:17, nombre:"App de Finanzas para Autónomos", emoji:"💸", sector:"Tech", potencial:"Alta", dificultad:"Moderada", resumen:"Gestoría digital que automatiza la facturación, el cálculo del IVA trimestral, el IRPF y la comunicación con la AEAT.", por_que:"Quickbooks Self-Employed tiene 800.000 usuarios en EE.UU. Countingup (UK) tiene 80.000 autónomos y fue valorada en 200M$. Holded (española) fue adquirida por Visma por 100M€. El autónomo español dedica 8 horas mensuales de media a gestiones administrativas (estudio Sage 2024), tiempo que facturaría a 30-80€/hora.", como_aplicar:"España tiene 3,3 millones de autónomos, el 65% sin software de gestión específico para su sector. Getquipu (150.000 usuarios), Declarando y Quipu existen pero son genéricos. Una solución vertical para un sector (ej: autónomos digitales: diseñadores, programadores, consultores) con integración directa con la AEAT Veri*factu y factura electrónica obligatoria desde 2025 tiene urgencia de mercado real.", riesgos:["Regulación fiscal española cambia frecuentemente: requiere equipo legal/fiscal interno para actualizaciones","Responsabilidad legal si hay errores en declaraciones: necesitas seguro de responsabilidad profesional","Competencia de gestorías tradicionales que se digitalizan y bancos que ofrecen servicios similares"], pasos:["Elegir nicho: autónomos digitales tienen mayor disposición a pagar y mayor adopción tecnológica","Integración con AEAT para presentación directa de modelos 303 (IVA) y 130 (IRPF) desde el día 1","Precio 19-39€/mes con primer trimestre gratis para capturar mercado en período crítico de Veri*factu","Canal: comunidades de freelancers en LinkedIn, Slack (grupos de diseño/desarrollo español) y Twitter/X"] },

  { id:18, nombre:"Software de Fidelización para Comercio Local", emoji:"🏪", sector:"Tech", potencial:"Alta", dificultad:"Fácil", resumen:"App de sellos digitales y recompensas para que el comercio local fidelice clientes como las grandes cadenas, a precio de PYME.", por_que:"Stamp Me tiene 4 millones de usuarios. Fivestars (EE.UU.) sirve a 14.000 comercios locales y fue adquirida por SumUp por 317M$. El comercio local que implementa un programa de fidelización aumenta la frecuencia de visita un 35% y el ticket medio un 22% (estudio Nielsen 2023). El coste de retener a un cliente es 5 veces menor que captar uno nuevo.", como_aplicar:"El 94% del comercio local español no tiene programa de fidelización digital (CNMC 2024). Una app con sello digital, notificaciones push personalizadas y sistema de puntos canjeables por descuentos a 19-39€/mes tiene argumento de venta muy sencillo: 'Lo que hace el Corte Inglés, pero para tu tienda, por 1€/día'.", riesgos:["Adopción del cliente final es el mayor obstáculo: necesitas que el comerciante promueva la app activamente","Mercado local requiere fuerza de ventas presencial: coste de adquisición alto (150-300€ por comercio)","Diferenciación difícil a largo plazo frente a soluciones gratuitas básicas de Instagram o WhatsApp Business"], pasos:["MVP: app de cliente (iOS/Android) + panel web para el comerciante, no necesitas más para empezar","Venta puerta a puerta en polígono comercial o mercado de abastos (100 comercios en 2 días)","Modelo freemium: gratis hasta 50 clientes registrados, luego 29€/mes","Crear asociación con gremios de comerciantes locales para acceso masivo y validación colectiva"] },

  { id:19, nombre:"Plataforma de Cursos para Oficios Técnicos", emoji:"🔧", sector:"Tech", potencial:"Alta", dificultad:"Moderada", resumen:"Formación online certificada para fontaneros, electricistas, instaladores de renovables y técnicos de HVAC.", por_que:"Interplay Learning (EE.UU.) fue valorada en 200M$+ con 50.000 técnicos formados. El mercado de formación técnica online alcanzará 6.000M$ en 2026. EE.UU. tiene un déficit de 400.000 técnicos de oficios cualificados. Las empresas del sector pagan la formación de sus empleados porque no encuentran profesionales: el B2B genera contratos de 50.000-500.000€.", como_aplicar:"España tiene déficit de 150.000 instaladores de energía solar (APPA Renovables 2024) para alcanzar los objetivos del PNIEC 2030. El SEPE subvenciona formación continua hasta 6.000€ por empresa al año. Una academia con certificados avalados por fabricantes (SunPower, Bosch Thermotechnology) y combinación 80% online + 20% presencial en instalaciones reales puede vender a instaladoras que necesitan formar urgentemente a su equipo.", riesgos:["Certificaciones oficiales requieren homologación del Ministerio de Educación: proceso de 12-24 meses","Producción de video técnico de calidad cuesta 500-2.000€ por hora de contenido","Cambio tecnológico rápido obliga a actualización constante del temario con coste asociado"], pasos:["Empezar con un único oficio: instalación de paneles fotovoltaicos (máxima demanda y urgencia)","Alianza con fabricante de paneles para certificación y acceso a su red de instaladoras como canal de venta","Formato híbrido: 20 horas online + 8 horas presenciales en empresa colaboradora","Solicitar subvenciones SEPE para formación continua: te permiten ofrecer el curso a empresas a coste cero"] },

  // ── RETAIL ───────────────────────────────────────────────────
  { id:20, nombre:"Tiendas de Segunda Mano Especializadas", emoji:"♻️", sector:"Retail", potencial:"Alta", dificultad:"Fácil", resumen:"Tiendas físicas de ropa, electrónica o juguetes de segunda mano con curaduría, garantía y experiencia de compra premium.", por_que:"ThredUp (EE.UU.) procesa 100 millones de prendas anuales y vale 1.500M$. El mercado global de segunda mano alcanzará 350.000M$ en 2027 (ThredUp Report 2024), creciendo 3 veces más rápido que el mercado de moda convencional. El comprador de segunda mano curada paga un 40-60% del precio original, generando márgenes del 200-300% sobre el coste de adquisición.", como_aplicar:"Wallapop factura 100M€ en España pero es peer-to-peer sin curaduría. Una tienda física especializada (solo ropa deportiva premium, solo electrónica Apple, solo juguetes educativos) con garantía de 6 meses, fotografía profesional y pricing inteligente puede generar 8.000-20.000€/mes de facturación en un local de 60-80m². El modelo de consignación (50/50 con el vendedor) elimina el riesgo de stock.", riesgos:["Aprovisionamiento de piezas de calidad es el principal cuello de botella y tarda 3-6 meses en estabilizarse","Gestión de inventario con SKUs únicos por pieza es 10 veces más compleja que el retail convencional","Local en zona prime con alto tráfico puede costar 3.000-6.000€/mes de alquiler, erosionando márgenes"], pasos:["Comenzar sin local: validar demanda vendiendo en Vinted, Wallapop e Instagram durante 3 meses","Modelo de consignación: el proveedor trae su ropa, tú la vendes y os repartís al 50%","Local en mercado de segunda mano o centro comercial con alquiler variable (% de ventas) para minimizar riesgo","Software de gestión de inventario especializado: Ricochet o ConsignCloud desde el día 1"] },

  { id:21, nombre:"Suscripción de Productos Artesanales Locales", emoji:"🧀", sector:"Retail", potencial:"Alta", dificultad:"Fácil", resumen:"Caja mensual curada con productos artesanales de productores locales: quesos, embutidos, aceites, vinos, conservas.", por_que:"Cratejoy (EE.UU.) procesa 35 millones de cajas de suscripción anuales. Goldbelly factura 100M$+ enviando comida artesanal americana. El mercado de suscription boxes creció un 41% en 2023 en España. El LTV promedio de un suscriptor de caja gourmet es de 18 meses y 900€ totales. El cliente no compra el producto, compra el descubrimiento y la historia detrás del productor.", como_aplicar:"España tiene la mayor densidad de productos con Denominación de Origen Protegida del mundo: 345 DOP/IGP (MAPA 2024). Una caja mensual de 39-79€ curada por región (caja de Extremadura, caja del País Vasco, caja de Murcia) con historia del productor, recetas y maridaje tiene demanda tanto en España como en la diáspora española en el extranjero y entre turistas que quieren llevarse España a casa.", riesgos:["Logística de temperatura controlada para quesos y embutidos añade 3-6€ por envío al coste","Retención de suscriptores cae drásticamente si el contenido se repite o la calidad varía","Negociación con productores artesanales pequeños es lenta: no tienen procesos de venta B2B establecidos"], pasos:["Definir región o temática muy concreta: 'Los mejores quesos de España' o 'Aceites de oliva virgen extra premiados'","Validar con 30 suscriptores piloto durante 3 meses antes de invertir en fotografía y web profesional","Fotografía de producto premium: el 80% de la conversión en este modelo depende de las fotos de Instagram","Canal inicial: grupos de foodies en Facebook, comunidades de expatriados españoles en Instagram"] },

  { id:22, nombre:"Live Commerce (Ventas en Directo)", emoji:"📺", sector:"Retail", potencial:"Alta", dificultad:"Fácil", resumen:"Ventas en streaming en directo en TikTok Shop o Instagram Live con descuentos exclusivos y compra en tiempo real.", por_que:"En China el live commerce mueve 720.000M$ anuales (eMarketer 2024), el 23% del total del e-commerce. En EE.UU. alcanzó 68.000M$ en 2023, crecimiento del 30%. TikTok Shop se lanzó en EE.UU. en 2023 y en su primer año procesó más de 10.000M$ en ventas. El valor medio de un pedido por live commerce es un 40% superior al de e-commerce tradicional.", como_aplicar:"España está en el año 0 del live commerce: TikTok Shop se lanzó en España en 2024. Las marcas que dominen el formato ahora tienen ventaja de primer movimiento de 2-3 años antes de que el canal se sature. Los sectores que mejor convierten en live: moda (especialmente segunda mano), cosméticos, alimentación gourmet y gadgets. Una tienda con 2 directos semanales de 45 minutos puede generar 5.000-30.000€/mes en facturación.", riesgos:["Requiere persona con carisma natural ante cámara: no todo vendedor funciona en este formato","Gestión de stock en tiempo real durante el directo: agotados o errores de precio dañan la reputación","Algoritmos de TikTok e Instagram pueden cambiar el alcance orgánico sin previo aviso"], pasos:["Elegir plataforma según público: TikTok si tu producto es visual y tu público <35 años; Instagram si es >35","Empezar con 2 directos semanales de 45 min con 10-15 productos estrella seleccionados con descuento exclusivo","Crear urgencia: contador regresivo, stock visible en pantalla, ofertas que caducan al acabar el directo","Colaborar con otro creador para crecer audiencia mutuamente en los primeros 3 meses"] },

  { id:23, nombre:"Renting de Herramientas Entre Particulares", emoji:"🔨", sector:"Retail", potencial:"Alta", dificultad:"Moderada", resumen:"Plataforma peer-to-peer de alquiler de herramientas, equipos de bricolaje y maquinaria para particulares y pymes.", por_que:"Sunbelt Rentals (EE.UU.) genera 5.600M$+ anuales. El 90% de las herramientas se usan menos de 12 veces en su vida útil. Fat Llama (UK, alquiler de cualquier cosa) fue adquirida por Hygglo (sueco). El modelo es el 'Airbnb de las herramientas': el propietario genera ingresos extra y el arrendatario accede a herramientas sin comprarlas.", como_aplicar:"España tiene 19 millones de hogares y un mercado de bricolaje de 3.500M€ anuales. El 68% de españoles hace bricolaje ocasionalmente pero no quiere comprar herramientas específicas para un uso único. Un taladro Bosch de calidad vale 150€ pero se puede alquilar por 8-15€/día generando al propietario 300-600€/año pasivos. La plataforma cobra 25-30% de comisión.", riesgos:["Seguro de daños durante el alquiler: solución compleja y cara que requiere acuerdo con aseguradora específica","Logística de recogida y entrega entre particulares: la fricción mata el modelo si no se soluciona bien","Masa crítica necesaria: necesitas 500+ herramientas disponibles en una ciudad para que la experiencia funcione"], pasos:["Empezar con modelo B2C propio: tienda de alquiler con stock propio (inversión 20.000-40.000€)","Categorías iniciales de mayor demanda: taladros, andamios, cortacéspedes, hormigoneras, herramientas de pintura","App de reservas + pago online + sistema de depósito con tarjeta para cubrir posibles daños","Expandir a modelo P2P cuando tengas 200+ clientes activos que confíen en la plataforma"] },

  { id:24, nombre:"Renting de Ropa por Suscripción", emoji:"👗", sector:"Retail", potencial:"Media", dificultad:"Difícil", resumen:"Suscripción mensual de alquiler de ropa de diseño y marcas premium: la usas, la devuelves, siempre tienes ropa nueva.", por_que:"Rent the Runway (EE.UU.) fue valorada en 1.700M$ en su IPO con 125.000 suscriptores activos a 89-144$/mes. Nuuly (URBN) tiene 200.000+ suscriptores. El modelo resuelve el 'problema del armario lleno pero sin qué ponerse': el 35% de las mujeres profesionales de 25-40 años declara que ropa apropiada para el trabajo es su mayor gasto de moda.", como_aplicar:"En España Dressr y Etiqueta Negra operan este modelo pero a escala pequeña. El nicho de mayor oportunidad es ropa de trabajo de calidad para mujeres directivas (trajes, blazers, vestidos de reunión): prendas de 300-800€ que se usan pocas veces. Una suscripción de 79-149€/mes con 4 prendas rotativas tiene ROI claro para la clienta vs compra.", riesgos:["Capital necesario para stock inicial es muy alto: mínimo 100.000€ para tener 500 prendas de calidad","Logística de limpieza (tintorería industrial) añade 8-15€ por prenda devuelta al coste operativo","Tasa de abandono del 40-60% en los primeros 6 meses si la curaduría no satisface las preferencias de estilo"], pasos:["Empezar con nicho muy específico: solo vestidos de fiesta o solo ropa de trabajo para abogadas/consultoras","Acuerdo con tintorería industrial local para gestión de limpieza con SLA garantizado","App o Instagram + WhatsApp para selección de prendas en las primeras fases","Lanzar con 20 suscriptoras piloto durante 3 meses para identificar los problemas operativos antes de escalar"] },

  // ── SERVICIOS ────────────────────────────────────────────────
  { id:25, nombre:"Gestión de Alquiler Vacacional", emoji:"🏡", sector:"Servicios", potencial:"Alta", dificultad:"Fácil", resumen:"Empresa que gestiona integralmente propiedades de Airbnb y Booking: check-in, limpieza, precios dinámicos y atención 24h.", por_que:"Vacasa (EE.UU.) gestiona 35.000 propiedades y cotiza en el Nasdaq. AvantStay fue valorada en 500M$. El mercado de gestión de alquiler vacacional alcanzará 115.000M$ en 2030. El propietario que usa gestión profesional aumenta sus ingresos un 40% de media respecto a la autogestión (datos Airbnb 2024).", como_aplicar:"España es el segundo destino turístico mundial con 2,9 millones de viviendas turísticas (MIVAU 2024). El 73% de propietarios gestiona sus pisos de forma amateur, dejando dinero encima de la mesa. Una empresa de gestión que garantice 'más ingresos que gestionándolo tú solo o te devolvemos el mes' cobra 20-25% de los ingresos generados sin riesgo para el propietario.", riesgos:["Regulación de alquiler vacacional cambia por ciudad con restricciones severas en Barcelona, Madrid y Palma","Gestión de personal de limpieza en temporada alta es el mayor cuello de botella operativo","Un huésped problemático que causa daños puede destruir la relación con el propietario irreparablemente"], pasos:["Empezar gestionando 5-10 propiedades de conocidos para construir procesos y referencias","Software desde día 1: Hostaway (120€/mes) para gestión multicanal y PriceLabs para pricing dinámico","Acuerdo exclusivo con empresa de limpieza de confianza con SLA de 3 horas entre salida y entrada","Propuesta de valor clara: 'Gestionamos tu piso mejor que tú y cobramos solo si generamos más ingresos'"] },

  { id:26, nombre:"Fotografía Inmobiliaria con Dron y Virtual Tour", emoji:"📸", sector:"Servicios", potencial:"Alta", dificultad:"Fácil", resumen:"Servicio profesional de fotografía, vídeo con dron y tour virtual 360° para inmobiliarias y propietarios particulares.", por_que:"Las inmobiliarias con fotografía profesional en EE.UU. venden un 32% más rápido y a un 11% más de precio (NAR 2024). Matterport (tours virtuales) tiene 7 millones de espacios digitalizados y fue adquirida por CoStar por 1.600M$. El 87% de compradores de vivienda en España empieza su búsqueda online (idealista 2024): la primera impresión es la foto.", como_aplicar:"El 68% de anuncios en Idealista tiene fotografías de baja calidad tomadas con móvil (estudio Idealista 2023). Una empresa especializada que ofrece fotografía profesional (2h de sesión + edición), vídeo con dron exterior y tour virtual Matterport por 249-449€ por propiedad tiene argumento de venta irrefutable: 'La mejor inversión que puedes hacer para vender tu piso'.", riesgos:["Licencia de operador de dron (UAS) de AESA: proceso de 3-6 meses y coste de 500-1.000€","Equipo completo (cámara full-frame, gran angular, dron DJI, suscripción Matterport): 8.000-15.000€ de inversión inicial","Negocio de repetición baja: hay que fidelizar a la inmobiliaria, no al propietario particular"], pasos:["Obtener licencia de operador de dron en AESA (cursos de 200-400€ + seguro obligatorio)","Equipo esencial: Sony A7IV + Sigma 16mm + DJI Mavic 3 Pro + cámara Matterport Pro3","Visitar en persona a 20 inmobiliarias con tablet mostrando ejemplos en comparativa: fotos de móvil vs profesional","Modelo de precios: 149€ (solo fotos), 249€ (fotos + dron), 399€ (pack completo con Matterport)"] },

  { id:27, nombre:"Concierge para Personas Mayores", emoji:"👴", sector:"Servicios", potencial:"Alta", dificultad:"Fácil", resumen:"Servicio de asistencia personal para mayores: acompañamiento médico, trámites digitales, compras, tecnología y visitas.", por_que:"Papa Inc. (EE.UU.) fue valorada en 1.400M$ conectando a mayores con 'compañeros'. Honor Care vale 1.700M$. EE.UU. tiene 54 millones de personas >65 años y el mercado de senior care alcanzará 830.000M$ en 2030. El 67% de adultos mayores tiene al menos un hijo que vive lejos y no puede cuidarlos diariamente, creando una culpa que se convierte en disposición a pagar.", como_aplicar:"España es el segundo país más envejecido de la UE: 9,3 millones de personas >65 años (INE 2024), proyectados a 13 millones en 2035. Las familias de clase media-alta que no pueden atender a sus mayores diariamente pagan 150-350€/mes por tranquilidad. La escasez de ayuda a domicilio pública (lista de espera de 18 meses) crea urgencia de mercado real.", riesgos:["Confianza del cliente es el mayor activo y el mayor riesgo: un incidente destruye la reputación completamente","Regulación laboral específica para cuidadores: convenio de ayuda a domicilio y seguros obligatorios","Escalar requiere selección muy exigente de personal: el 80% de candidatos no supera el proceso de verificación"], pasos:["Definir catálogo concreto y acotado: no 'todo', sino 5-8 servicios específicos (médico, farmacia, banco, tecnología, acompañamiento)","Proceso de selección riguroso: antecedentes penales, referencias verificadas, formación en primeros auxilios","Captar primeros clientes por médicos de cabecera, farmacéuticos y trabajadores sociales como prescriptores clave","Suscripción mensual de 150-250€ con 10 horas incluidas + tarifa extra por hora adicional"] },

  { id:28, nombre:"Servicios de Bienestar Corporativo", emoji:"🏢", sector:"Servicios", potencial:"Alta", dificultad:"Fácil", resumen:"Programas de salud mental, yoga, nutrición y ergonomía para empleados, contratados mensualmente por empresas.", por_que:"El mercado de corporate wellness en EE.UU. alcanza 53.000M$ anuales y crece al 6,5% anual (GWMS 2024). Gympass (brasileño) fue valorado en 2.200M$ en EE.UU. Las empresas reducen el absentismo laboral un 27% con programas de bienestar activos (estudio Deloitte 2024) y mejoran la retención de talento un 31%.", como_aplicar:"La Ley de Prevención de Riesgos Laborales española obliga a las empresas a vigilar la salud de sus empleados, pero el 90% cumple solo el mínimo legal. Una empresa que ofrece un programa mensual de 10-15€/empleado/mes con yoga online, sesiones de nutrición, psicología preventiva y ergonomía tiene ROI demostrable para RRHH y cumple obligaciones legales.", riesgos:["Decisión de compra en área de RRHH con presupuesto limitado y ciclo de aprobación de 2-4 meses","Demostrar ROI es condición para renovar: necesitas métricas de bienestar antes y después del programa","Competencia de mutuas laborales que ofrecen servicios similares a coste inferior o cero"], pasos:["Paquete inicial mínimo: 2 clases de yoga online semanales + 1 charla mensual de nutrición + evaluación ergonómica anual","Conseguir primeras 3 empresas de 50-200 empleados con descuento de lanzamiento del 50% para primeros 6 meses","Medir y reportar mensualmente: asistencia, satisfacción, reducción de bajas por ansiedad","Alianzas con psicólogos, nutricionistas y entrenadores autónomos para cubrir servicios sin contratarlos"] },

  { id:29, nombre:"Asistente Virtual para PYMEs y Autónomos", emoji:"💼", sector:"Servicios", potencial:"Alta", dificultad:"Fácil", resumen:"Servicio de asistente virtual que gestiona emails, agenda, redes sociales, facturación y tareas administrativas recurrentes.", por_que:"Time Etc (UK) tiene 23.000 empresas clientes. Fancy Hands (EE.UU.) procesa 1 millón de tareas mensuales. El empresario pequeño dedica el 41% de su tiempo a tareas administrativas no estratégicas (estudio McKinsey 2024), equivalente a 2 días laborables semanales que podría dedicar a vender o crear.", como_aplicar:"España tiene 2,9 millones de autónomos que trabajan solos y 1,5 millones de microempresas de 1-5 empleados que no pueden permitirse un empleado administrativo pero sí pueden pagar 300-600€/mes por 10-20 horas de asistencia virtual de calidad. El diferenciador frente a asistentes de India o Latinoamérica es el conocimiento del contexto fiscal y empresarial español.", riesgos:["Precio presionado por competencia de países con costes laborales bajos (50-80€/mes vs 300-600€)","Confianza y confidencialidad son barreras de entrada: el empresario tarda en delegar acceso a su email y cuentas","Escalabilidad limitada: cada asistente puede gestionar máximo 4-6 clientes, lo que limita el crecimiento"], pasos:["Definir 5-8 servicios concretos y no 'todo': especialización genera más confianza y precio más alto","Empezar con 3-5 clientes piloto a 200€/mes durante 2 meses para afinar procesos y detectar problemas","Sistema de gestión compartida: Google Workspace + Notion + Loom para comunicación asíncrona eficiente","Canal de captación: networking de emprendedores (coworkings, eventos startup) y grupos de empresarios en LinkedIn"] },

  { id:30, nombre:"Mudanzas con Valoración y Reventa de Objetos", emoji:"📦", sector:"Servicios", potencial:"Media", dificultad:"Fácil", resumen:"Empresa de mudanzas que también gestiona la venta, donación o reciclaje de los objetos que el cliente no quiere llevarse.", por_que:"1-800-GOT-JUNK (EE.UU.) genera 500M$ anuales solo en recogida de residuos voluminosos. LoadUp genera 50M$. El modelo de 'mudanza circular' añade una segunda fuente de ingresos: objetos que el cliente no quiere se venden en segunda mano (eBay, Facebook Marketplace) y se reparte el beneficio. El cliente paga menos por la mudanza y la empresa gana en ambos lados.", como_aplicar:"España tiene 700.000 mudanzas anuales (FETEIA 2024) y el vaciado de pisos es un mercado de 200M€ que crece con el envejecimiento poblacional (herencias, residencias). Una empresa que ofrece 'mudanza + vaciado + reventa' con transparencia total sobre lo obtenido en la reventa tiene propuesta diferenciada en un mercado completamente comoditizado por precio.", riesgos:["Logística de dos servicios en paralelo (mudanza + recogida/venta de objetos) es operativamente compleja","Valoración de objetos puede generar conflictos con el cliente si no se pacta previamente por escrito","Almacenamiento temporal de objetos para venta requiere espacio físico y genera coste fijo"], pasos:["Empezar ofreciendo solo vaciado de pisos (más sencillo que mudanzas completas, menos competencia)","Acuerdo previo con tiendas de segunda mano locales y chatarrerías para compra rápida de objetos","Contrato de servicio claro: qué objetos se venden, qué precio mínimo se acepta, cómo se reparte el beneficio","Canal de captación: inmobiliarias (pisos heredados), gestores de residencias y funerarias como prescriptores"] },

  // ── EDUCACIÓN ────────────────────────────────────────────────
  { id:31, nombre:"Tutorías Online con IA + Tutor Humano", emoji:"📚", sector:"Educación", potencial:"Alta", dificultad:"Moderada", resumen:"Plataforma de refuerzo escolar donde la IA diagnostica lagunas y un tutor humano las resuelve en sesiones personalizadas.", por_que:"Varsity Tutors (EE.UU.) fue adquirida por Nerdy Inc. por 776M$. Khan Academy Khanmigo (IA) tiene 5 millones de usuarios. El mercado de tutoría online alcanzará 31.000M$ en 2028. La combinación IA+humano mejora el rendimiento académico un 47% más que la tutoría solo humana (MIT Media Lab 2023) porque la IA identifica lagunas específicas que el tutor humano luego trabaja.", como_aplicar:"España tiene 8 millones de estudiantes de ESO y Bachillerato, con el 32% suspendiendo alguna asignatura (Ministerio de Educación 2024). El mercado de academias de refuerzo es de 1.800M€ anuales pero está fragmentado en academias físicas de barrio. Una plataforma a 79-149€/mes por asignatura con diagnóstico IA gratuito como lead magnet tiene diferenciación clara y escalabilidad nacional.", riesgos:["Captación costosa: la decisión la toma el padre pero la motivación la tiene el alumno, dinámicas difíciles de manejar","Resultados académicos difíciles de atribuir a tu plataforma en exclusiva (también hay esfuerzo del alumno)","Estacionalidad brutal: 70% de los ingresos se concentran entre septiembre-diciembre y febrero-mayo"], pasos:["Empezar con Matemáticas de ESO: mayor demanda, más fácil medir resultados y comparar con notas del colegio","Reclutar tutores universitarios de 4º y 5º de carrera: alta calidad, disponibilidad flexible y coste 12-18€/hora","Diagnóstico inicial gratuito de 20 minutos como gancho de captación (genera datos + crea compromiso)","Canal principal de captación: grupos de padres en WhatsApp por colegio y Facebook Ads geo-segmentados"] },

  { id:32, nombre:"Academia de Finanzas Personales", emoji:"💰", sector:"Educación", potencial:"Alta", dificultad:"Fácil", resumen:"Cursos estructurados, comunidad y herramientas para gestionar dinero personal, invertir y planificar la jubilación.", por_que:"Ramsey Solutions (EE.UU.) genera 300M$+ con cursos de finanzas personales. I Will Teach You To Be Rich de Ramit Sethi factura 50M$+. El 76% de americanos vive al día sin ahorros (CNBC 2024). En España el problema es similar: el 58% no tiene ahorros de emergencia (Banco de España 2024) y la tasa de participación en fondos de inversión es la más baja de la UE.", como_aplicar:"El mercado de educación financiera personal en España es prácticamente virgen: El Podcast de Alex Fidalgo tiene 500.000 oyentes pero sin producto de pago. Un programa de 90 días estructurado (semana 1: presupuesto, semana 2-4: deudas, mes 2: ahorro, mes 3: inversión básica) con comunidad de Discord y herramientas (plantilla de presupuesto, comparador de fondos) a 197-497€ tiene conversión alta con audiencia previa.", riesgos:["Sin licencia CNMV no puedes dar asesoramiento financiero personalizado: el curso debe ser educación genérica, no consejos","Credibilidad del instructor es absolutamente fundamental: el cliente investiga tu patrimonio y resultados personales","Contenido gratuito de calidad en YouTube (Carlos Galán, Marcos Luque) compite directamente con tu producto de pago"], pasos:["Construir audiencia gratuita durante 6-12 meses en TikTok e Instagram con contenido de finanzas personales antes de vender","Diseñar programa de 90 días con hitos específicos y medibles: '1.000€ ahorrados en 90 días o te devolvemos el dinero'","Diferenciar claramente de asesoramiento financiero en toda la comunicación para evitar problemas regulatorios","Comunidad de Discord o Telegram como valor añadido clave: los alumnos se quedan por la comunidad, no solo por el contenido"] },

  { id:33, nombre:"Bootcamps de Programación para Reconversión", emoji:"👩‍💻", sector:"Educación", potencial:"Alta", dificultad:"Difícil", resumen:"Programas intensivos de 4-6 meses para cambiar de carrera hacia el sector tech sin experiencia técnica previa.", por_que:"General Assembly (EE.UU.) fue adquirida por Adecco por 412M$. Lambda School tiene 20.000 graduados. El sector tech en España paga un 67% más de media que el salario nacional (InfoJobs 2024) y tiene 112.000 posiciones sin cubrir (DigitalES 2024). El ROI del bootcamp es claro: inversión de 6.000-12.000€ para pasar de salario de 18.000€ a 28.000-40.000€ en 12 meses.", como_aplicar:"Ironhack, Nuclio Digital School y The Bridge operan en España pero tienen listas de espera de 3-6 meses. Los perfiles más demandados son Data Analyst, Frontend Developer y Product Manager. Un bootcamp especializado en un único perfil muy demandado (ej: solo Data Analytics para no técnicos) con garantía de empleo en 6 meses y modelo de ISA (pagar con % del sueldo futuro) tiene propuesta imbatible.", riesgos:["Inversión inicial alta: profesorado de calidad cuesta 40.000-80.000€/año por instructor senior","Reputación depende 100% del porcentaje de colocación laboral: si baja del 80%, el negocio colapsa","Regulación de enseñanza no reglada varía por comunidad autónoma: consultoría legal antes de empezar"], pasos:["Especializarse en UN único perfil: Data Analyst es el más demandado y más accesible para no técnicos","Alianzas con 10-15 empresas tecnológicas para colocación garantizada antes de abrir la primera edición","Primera edición a precio reducido (3.000-4.000€ vs 8.000-10.000€ estándar) para construir casos de éxito reales","Modelo de financiación: acuerdo con entidad financiera para ISA (Income Share Agreement) o financiación a 0%"] },

  { id:34, nombre:"Formación en Oficios de la Transición Energética", emoji:"⚡", sector:"Educación", potencial:"Alta", dificultad:"Moderada", resumen:"Cursos certificados para instaladores de paneles solares, técnicos de bombas de calor, cargadores de vehículo eléctrico y eficiencia energética.", por_que:"El mercado de formación en energías renovables en EE.UU. alcanzará 12.000M$ en 2030. España necesita 200.000 técnicos adicionales para cumplir el PNIEC 2030 (APPA Renovables 2024). Las empresas instaladoras pagan formación porque no encuentran profesionales: contratos B2B de 50.000-300.000€/año son habituales en EE.UU.", como_aplicar:"España instaló 9 GW de solar en 2023 y planea 57 GW adicionales antes de 2030. Cada GW requiere 3.000 instaladores. El SEPE subvenciona formación continua con hasta 6.000€ anuales por empresa, lo que permite ofrecer formación gratuita o muy subsidiada como ventaja competitiva. Un curso de 40 horas para instalador fotovoltaico con certificado avalado por fabricante (Fronius, SMA) tiene demanda inmediata.", riesgos:["Homologación oficial del Ministerio de Industria para algunos certificados: proceso de 12-18 meses","Producción de contenido técnico de video con instalaciones reales: 1.000-3.000€ por hora de contenido","Cambio tecnológico rápido (perovskita, almacenamiento, hidrógeno) obliga a actualización constante del temario"], pasos:["Alianza estratégica con fabricante de inversores o paneles para certificación con su marca (Fronius Academy, etc.)","Formato obligatorio: 60% online asíncrono + 40% presencial en instalación real con empresa colaboradora","Canal B2B primero: instaladoras solares medianas (10-50 empleados) que necesitan formar urgentemente a su equipo","Solicitar acreditación ESCO (Energy Service Company) para acceder a subvenciones europeas del programa LIFE"] },

  { id:35, nombre:"Escuela de Habilidades Digitales para +45 años", emoji:"💻", sector:"Educación", potencial:"Alta", dificultad:"Fácil", resumen:"Formación práctica en herramientas digitales, IA y software para trabajadores senior que quieren mantenerse competitivos.", por_que:"AARP (EE.UU.) genera 1.500M$ en servicios para mayores de 50 años. El 78% de trabajadores de +45 años teme quedarse obsoleto tecnológicamente (encuesta LinkedIn 2024). En EE.UU. las empresas gastan 50.000M$+ anuales en upskilling digital de sus empleados mayores para evitar despidos y EREs. El comprador corporativo paga 500-2.000€ por empleado sin negociar.", como_aplicar:"España envejece laboralmente: la edad media del trabajador español es 42 años (INE 2024) y las empresas buscan reciclar a sus empleados senior antes que despedirlos (coste legal y reputacional). Un programa de 20 horas en 5 semanas sobre 'IA para tu trabajo diario' (ChatGPT, Copilot, automatización con Zapier) vendido a empresas a 999€ por grupo de 10 empleados tiene ventas cerradas en tiempo récord.", riesgos:["Diseño pedagógico debe ser extremadamente accesible: nada de jerga técnica, todo orientado a tareas concretas del trabajo diario","El canal B2B (RRHH de empresas) tiene ciclo de aprobación lento: 2-4 meses desde contacto hasta factura","Actualización constante necesaria: la IA evoluciona cada 3-6 meses, el temario se queda obsoleto rápido"], pasos:["Crear módulo piloto de 2 horas: 'ChatGPT para reducir tu trabajo administrativo a la mitad'","Precio de validación: 99€/persona o 799€ por grupo de hasta 10 (accesible para que digan sí sin deliberar)","Canal: LinkedIn Ads segmentados a directores de RRHH y responsables de formación de empresas de +50 empleados","Alianza con consultoras de RRHH y ETTs como distribuidores: te dan acceso a sus bases de clientes"] },

  // ── SOSTENIBILIDAD ───────────────────────────────────────────
  { id:36, nombre:"Energía Solar Comunitaria", emoji:"☀️", sector:"Sostenibilidad", potencial:"Alta", dificultad:"Difícil", resumen:"Comunidades de propietarios que comparten instalación solar fotovoltaica en tejado y reparten el ahorro en factura.", por_que:"En EE.UU. el mercado de community solar alcanzará 30.000M$ en 2030. España tiene 2.800 horas de sol anuales de media, el mayor recurso solar de Europa. La factura eléctrica media española es de 1.200€/año, un 40% superior a la media europea. Las instalaciones comunitarias amortización en 4-6 años y ahorran 400-800€/año por hogar.", como_aplicar:"El Real Decreto 244/2019 ya permite el autoconsumo colectivo en España pero menos del 0,1% de comunidades lo tiene implementado por la complejidad del trámite. Un intermediario que gestione todo el proceso (estudio de viabilidad gratuito, tramitación administrativa, instalación, mantenimiento, repartición del ahorro) con modelo de 0€ de entrada y cuota mensual inferior al ahorro generado tiene propuesta irresistible.", riesgos:["Aprobación en junta de propietarios requiere mayoría de 3/5 partes: proceso político interno complejo","Trámites con distribuidoras eléctricas (Endesa, Iberdrola) pueden durar 6-18 meses en algunos casos","Inversión inicial de la instalación (20.000-60.000€ por comunidad) requiere financiación propia o de terceros"], pasos:["Especializarse en tramitación de autoconsumo comunitario como servicio principal, no en instalación","Acuerdo con 2-3 instaladoras solares certificadas REE para subcontratar la obra","Modelo financiero: 0€ de entrada + cuota mensual de 80% del ahorro generado durante 10 años","Canal de captación: administradores de fincas (tienen acceso a miles de comunidades) como prescriptores remunerados"] },

  { id:37, nombre:"Reparación de Electrónica y Electrodomésticos", emoji:"🔌", sector:"Sostenibilidad", potencial:"Alta", dificultad:"Fácil", resumen:"Servicio de reparación profesional de móviles, portátiles, lavadoras y pequeño electrodoméstico con precio transparente y garantía.", por_que:"iFixit (EE.UU.) tiene 50 millones de usuarios y ha creado el movimiento 'Right to Repair'. La nueva Directiva Europea de Derecho a Reparar (2024) obliga a fabricantes a suministrar piezas de repuesto hasta 10 años después de la venta. España genera 900.000 toneladas de residuos electrónicos anuales (Eurostat 2024). El mercado de reparación de electrónica en Europa alcanzará 20.000M€ en 2027.", como_aplicar:"El 73% de españoles tiraría su móvil antes de repararlo por desconocer el precio (encuesta Rastreator 2024). Una empresa con precio fijo y transparente online (ej: 'Cambio de pantalla iPhone 14: 89€ con 1 año de garantía'), recogida a domicilio gratuita en 24h y reparación en 48h tiene propuesta de valor clarísima frente al servicio técnico oficial y las tiendas de barrio sin garantías.", riesgos:["Técnicos cualificados difíciles de encontrar y de retener: el mercado laboral del sector está desabastecido","Proveedores de piezas de repuesto no siempre fiables: una pieza defectuosa destruye la reputación","Algunos fabricantes (Apple especialmente) activamente dificultan el acceso a piezas y herramientas propietarias"], pasos:["Comenzar con reparación de móviles y portátiles: mayor volumen, piezas accesibles, margen del 60-80%","Certificarse como SAT (Servicio de Asistencia Técnica) de 2-3 marcas principales para acceso a piezas originales","Precio fijo online antes de traer el dispositivo como principal diferenciador: web con calculadora de precios","Servicio de recogida a domicilio en 24h: añade 15-20€ al ticket y multiplica el radio de acción geográfico"] },

  { id:38, nombre:"Gestión de Residuos para Hostelería", emoji:"🍃", sector:"Sostenibilidad", potencial:"Alta", dificultad:"Moderada", resumen:"Servicio que ayuda a bares y restaurantes a separar, reducir y valorizar sus residuos cumpliendo la normativa vigente.", por_que:"Rubicon Technologies (EE.UU.) gestiona residuos de 80.000 restaurantes y cotiza en NYSE. La nueva Ley de Residuos Española (7/2022) y la Ley de Residuos y Suelos Contaminados para una Economía Circular obligan a la hostelería a separar aceite usado, residuos orgánicos y envases desde 2024, con multas de hasta 45.000€ por incumplimiento.", como_aplicar:"España tiene 300.000 bares y restaurantes, la mayor concentración de Europa. El 87% no cumple correctamente con la separación de residuos (informe Ecoembes 2024) por desconocimiento y complejidad. Un servicio todo-incluido a 49-99€/mes que gestiona la recogida, la documentación legal y el cumplimiento normativo tiene argumento de venta urgente: 'evita una multa de 45.000€ por 99€ al mes'.", riesgos:["Logística de recogida propia es cara: necesitas furgoneta refrigerada para orgánico y ruta optimizada","Regulación varía significativamente entre comunidades autónomas y municipios: necesitas asesoramiento legal por región","Margen ajustado si el volumen por cliente es pequeño: necesitas mínimo 100 clientes activos para ser rentable"], pasos:["Empezar solo con recogida de aceite usado (ya tiene valorización económica: gestores pagan por el aceite)","Acuerdo con gestores de residuos autorizados SIGAUS para cada fracción (aceite, orgánico, envases, vidrio)","Primer canal: visitas puerta a puerta en polígonos de hostelería y mercados municipales con folleto de 'evita la multa'","Escalar a gestión integral (todas las fracciones) cuando tengas 50+ clientes de aceite y procesos rodados"] },

  { id:39, nombre:"Moda Sostenible de Producción Local", emoji:"👕", sector:"Sostenibilidad", potencial:"Media", dificultad:"Difícil", resumen:"Marca de ropa fabricada en España con materiales certificados sostenibles, trazabilidad total y transparencia de márgenes.", por_que:"Patagonia genera 1.400M$ con un modelo 100% sostenible. Everlane (EE.UU.) fue valorada en 1.700M$ con transparencia radical de precios. El mercado de moda sostenible alcanzará 9.100M$ en 2025 (Allied Market Research). El 73% de millennials pagaría más por una marca que demuestre impacto positivo (Nielsen 2024).", como_aplicar:"España tiene tradición textil histórica (Galicia, Cataluña, Comunidad Valenciana) con fábricas que buscan marca propia para sobrevivir a la competencia asiática. El sello 'Fabricado en España' tiene valor de percepción de calidad altísimo especialmente en mercados de exportación (Alemania, Francia, Países Bajos). Una marca D2C (venta directa sin intermediarios) con materiales GOTS certificados y margen transparente puede justificar precios de 40-120€ por básico.", riesgos:["Coste de producción local (25-50€ por camiseta) vs Asia (3-5€) hace muy difícil competir en precio","Construir marca de moda tarda mínimo 3-5 años y requiere inversión sostenida en marketing","Mercado de moda sostenible en España aún pequeño aunque creciente: adoptadores tempranos son minoría"], pasos:["Empezar con UNA sola prenda básica perfectamente ejecutada: la camiseta perfecta, el jersey perfecto","Certificar materiales: GOTS para algodón orgánico, GRS para materiales reciclados, OEKO-TEX para todo","Transparencia total de costes al estilo Everlane: 'Esta camiseta cuesta 12€ fabricarla, te la vendemos a 45€'","Canal D2C exclusivo: venta directa en web propia sin marketplace para defender margen y relación con cliente"] },

  { id:40, nombre:"Turismo Regenerativo", emoji:"🌿", sector:"Sostenibilidad", potencial:"Media", dificultad:"Moderada", resumen:"Agencia de viajes especializada en experiencias que mejoran activamente el destino visitado: reforestación, apoyo a comunidades locales, limpieza.", por_que:"El turismo regenerativo crece al 25% anual en EE.UU. y alcanzará 900M$ en 2026 (GSTC). El viajero consciente ya no quiere 'no dañar' (sostenible) sino 'mejorar activamente' (regenerativo). Empresas como Better Places (Países Bajos) tienen lista de espera de 3 meses con precios premium del 40-60% sobre turismo convencional.", como_aplicar:"España atrae 85 millones de turistas anuales pero enfrenta masificación severa en destinos clave (Canarias, Baleares, Barcelona) y despoblación extrema en zonas rurales. Una agencia que organiza experiencias de turismo regenerativo en zonas rurales de Castilla y León, Extremadura o Aragón (reforestación, restauración de muros de piedra, recuperación de cultivos tradicionales) con precio premium de 1.500-3.000€/semana tiene diferenciación única y apoyo institucional de los gobiernos autonómicos.", riesgos:["Greenwashing: el cliente exige impacto real, medible y certificado; la falta de estándares es un riesgo de credibilidad","Logística de actividades de impacto es compleja: coordinar ONG, propietarios de tierra, guías y turistas simultáneamente","Mercado aún pequeño en España aunque creciente: adoptadores tempranos son viajeros internacionales, no locales"], pasos:["Certificarse con organización reconocida: Travelife, Rainforest Alliance o la Carta del Turismo Sostenible de Lanzarote","Diseñar 3-5 experiencias específicas en zonas concretas con impacto medible (hectáreas reforestadas, empleos locales creados)","Alianza con ONGs ambientales locales para dar credibilidad científica al impacto","Canal de captación: tour operadores internacionales (alemanes, holandeses, escandinavos) especializados en turismo consciente"] },

  // ── INMOBILIARIO ─────────────────────────────────────────────
  { id:41, nombre:"Co-living para Jóvenes Profesionales", emoji:"🏠", sector:"Inmobiliario", potencial:"Alta", dificultad:"Difícil", resumen:"Espacios de vivienda compartida con habitaciones privadas, zonas comunes de calidad y comunidad curada, con todo incluido.", por_que:"Common (EE.UU.) gestiona 10.000 habitaciones en 22 ciudades. Quarters fue valorada en 300M$. El mercado global de co-living alcanzará 13.900M$ en 2025. El modelo genera un margen un 40-60% superior al alquiler tradicional por m²: una casa de 6 habitaciones a 700€/habitación genera 4.200€/mes vs 1.800€ de alquiler convencional.", como_aplicar:"España tiene el mayor problema de acceso a vivienda de la UE: el alquiler en Madrid ha subido un 68% en 5 años. Los jóvenes de 25-35 años pagan el 60% de su sueldo en alquiler en grandes ciudades. Un co-living a 700-1.000€/mes con habitación individual, baño privado, cocina equipada, limpieza quincenal, wifi de 1Gb, seguros incluidos y comunidad de jóvenes profesionales es competitivo frente a compartir piso a 550€ pero con la precariedad habitual.", riesgos:["Regulación de arrendamientos urbanos limita la capacidad de gestión flexible en España","Inversión inicial alta: reforma integral de inmueble para crear espacios de calidad (2.000-3.000€/m²)","Curación de la comunidad es difícil: un inquilino conflictivo destruye el valor para todos los demás"], pasos:["Acuerdo con propietario de edificio completo o varios pisos contiguos en contrato de gestión o arrendamiento de larga duración","Reforma orientada a co-living: habitaciones de 12-20m² con baño ensuite, cocina común amplia, sala de trabajo","App de comunidad propia para comunicación, reserva de servicios comunes y gestión de incidencias","Precio diferenciado por tipo: habitación estándar 700€, premium con baño ensuite 950€, suite 1.200€"] },

  { id:42, nombre:"Pop-up Stores y Espacios Temporales", emoji:"🏬", sector:"Inmobiliario", potencial:"Alta", dificultad:"Moderada", resumen:"Plataforma que conecta marcas online que quieren probar el formato físico con espacios disponibles por días, semanas o meses.", por_que:"Appear Here (UK/EE.UU.) tiene 10.000+ espacios listados y factura 50M$+. El 78% de marcas de e-commerce quiere presencia física temporal para validar producto sin comprometerse a un alquiler de 5 años. Los locales vacíos en España superan el 15% del total en zonas comerciales (CBRE 2024) y sus propietarios aceptan alquileres temporales antes que tenerlos vacíos.", como_aplicar:"España tiene 400.000 locales comerciales vacíos (INE 2024) y un boom de marcas nativas digitales que quieren tocar el mercado físico. Un marketplace que gestiona el proceso completo (contrato estándar, seguro temporal, limpieza, señalética básica) con precios de 100-800€/día según ubicación tiene valor claro para ambos lados. Madrid tiene alta concentración de marcas online con sede en la ciudad.", riesgos:["Efecto de red bilateral: necesitas simultáneamente locales y marcas en la misma ciudad, lo que ralentiza el inicio","Gestión de seguros, contratos y limpieza para cada ocupación temporal genera coste operativo alto","Estacionalidad marcada: 60% de la demanda se concentra en octubre-enero (campaña de Navidad)"], pasos:["Lanzar en una sola ciudad con 20 espacios curados y 30 marcas potenciales ya captadas antes de abrir","Precio estándar: 150-300€/día en zona media, 400-800€/día en zona prime (Serrano, Paseo de Gracia)","Contrato estandarizado de 1 página y seguro de responsabilidad civil incluido en el precio","Canal para espacios: agencias inmobiliarias con cartera de locales vacíos. Canal para marcas: inversores de startups de e-commerce"] },

  { id:43, nombre:"Asesoría de Compra de Vivienda para Jóvenes", emoji:"🔑", sector:"Inmobiliario", potencial:"Alta", dificultad:"Fácil", resumen:"Servicio de acompañamiento integral para primeros compradores: búsqueda, negociación, hipoteca y gestión de trámites.", por_que:"En EE.UU., Homelight fue valorada en 1.600M$ asesorando a compradores. Better.com (hipotecas online) alcanzó 7.000M$ de valoración. El 67% de compradores primerizos se siente 'perdido' en el proceso (NAR 2024) y busca asesoramiento neutral que no cobren las inmobiliarias tradicionales (que cobran solo al vendedor).", como_aplicar:"España tiene el proceso de compra de vivienda más complejo de Europa: ITP, AJD, nota simple, verificación de cargas, negociación de hipoteca, notaría, registro. El 82% de compradores primerizos comete al menos un error evitable con coste medio de 5.000-15.000€ (OCU 2024). Un servicio de 'personal shopper inmobiliario' a 2.000-4.000€ fijo (pagado por el comprador, no por el vendedor) tiene propuesta de valor ética e irrefutable.", riesgos:["Regulación de intermediación inmobiliaria: verificar si es necesaria habilitación oficial según comunidad autónoma","El cliente no está acostumbrado a pagar por asesoramiento inmobiliario (cultura de que 'lo paga el vendedor')","Competencia directa de API (Agentes de la Propiedad Inmobiliaria) que ofrecen este servicio gratuitamente"], pasos:["Crear contenido educativo sobre el proceso de compra (blog, Instagram, YouTube) para posicionarse como experto","Paquete de servicio claro: 'Te buscamos el piso, negociamos el precio y te acompañamos hasta la firma del notario'","Precio fijo transparente: 1.500€ (búsqueda básica) o 3.000€ (servicio completo incluyendo gestión de hipoteca)","Alianzas con corredores de hipotecas independientes para ofrecer el servicio de financiación como complemento"] },

  // ── MASCOTAS ─────────────────────────────────────────────────
  { id:44, nombre:"Hoteles de Lujo para Mascotas", emoji:"🐕", sector:"Mascotas", potencial:"Alta", dificultad:"Moderada", resumen:"Residencias premium para perros y gatos con habitaciones individuales, cámaras en vivo, actividades y servicio VIP.", por_que:"Dogtopia (EE.UU.) tiene 250+ franquicias y fue valorada en 200M$. Camp Bow Wow genera 120M$ anuales. El mercado de pet care en EE.UU. alcanzó 147.000M$ en 2023. El propietario de mascota americano gasta un 73% más en su perro que hace 10 años. La 'humanización' de las mascotas es la tendencia más sólida del sector.", como_aplicar:"España tiene 30 millones de mascotas (ANFAAC 2024) y el gasto por mascota ha crecido un 45% en 5 años. El 68% de propietarios declara que el principal obstáculo para viajar es 'qué hacer con el perro'. Una residencia con habitaciones individuales con cama, cámara 24h para que el dueño vea a su mascota, actividades diarias y menú premium a 35-65€/noche tiene diferenciación total respecto al típico kennnel de jaulas.", riesgos:["Licencia de centro de animales domésticos varía por municipio: proceso de 3-6 meses en muchos casos","Inversión en instalaciones: local con 200-400m², jardín obligatorio, ventilación específica: 80.000-150.000€","Un incidente con un animal (pelea, enfermedad) genera responsabilidad legal y daño reputacional grave"], pasos:["Estudiar normativa municipal de centros de animales domésticos antes de buscar local","Local de 250-400m² con acceso a jardín exterior en zona residencial con alta densidad de mascotas","Cámaras Wyze o similares en cada habitación individual para live streaming al app del dueño","Precio diferenciado: habitación estándar 35€/noche, suite con ventana al jardín 55€, servicio VIP 80€"] },

  { id:45, nombre:"Servicios de Salud Veterinaria Online", emoji:"🐾", sector:"Mascotas", potencial:"Alta", dificultad:"Moderada", resumen:"Plataforma de teleconsulta veterinaria 24h para resolver dudas, emitir recetas y hacer seguimiento de mascotas por videoconferencia.", por_que:"Pawp (EE.UU.) tiene 500.000 suscriptores a 24$/mes con 24h de acceso a veterinarios online. Dutch tiene 200.000 usuarios y fue valorada en 100M$. El 83% de visitas veterinarias de urgencias son por problemas que podrían resolverse con una teleconsulta (Journal of AVMA 2023). El mercado de telemedicina veterinaria alcanzará 1.200M$ en 2026.", como_aplicar:"España tiene 7 millones de perros y 5 millones de gatos con dueño. El coste de una urgencia veterinaria presencial es de 150-400€ mientras una teleconsulta costaría 25-40€. La Ley de Bienestar Animal de 2023 ha aumentado la responsabilidad del propietario sobre la salud de su mascota. Una plataforma con veterinarios colegiados disponibles en 10 minutos a 30€/consulta o 25€/mes de suscripción tiene propuesta clara.", riesgos:["Solo veterinarios con número de colegiado pueden emitir recetas: proceso de reclutamiento exigente y costoso","Responsabilidad legal si un diagnóstico incorrecto por videollamada lleva a consecuencias graves para el animal","Limitación técnica real: muchos problemas veterinarios requieren exploración física imposible por videollamada"], pasos:["Reclutamiento de 10-15 veterinarios autónomos colegiados con disponibilidad flexible a 20-30€/consulta","Plataforma técnica: Doctolib (adaptado) o desarrollo a medida con videollamada + historial + recetas digitales","Lanzar con modelo de pago por consulta (30€) antes de la suscripción para validar demanda real","Canal de captación: tiendas de alimentación animal, seguros de mascotas como distribuidores y grupos de Facebook de razas"] },

  { id:46, nombre:"Comida Natural y Personalizada para Mascotas", emoji:"🥩", sector:"Mascotas", potencial:"Alta", dificultad:"Moderada", resumen:"Suscripción de comida fresca para perros y gatos elaborada con ingredientes naturales y personalizada según las características del animal.", por_que:"The Farmer's Dog (EE.UU.) factura 400M$+ anuales y fue valorada en 2.700M$. Butternut Box (UK) tiene 250.000 suscriptores. El mercado de pet food premium crece al 15% anual en EE.UU. mientras el convencional decrece. El propietario moderno trata la alimentación de su mascota como la propia: el 64% declara leer los ingredientes de la comida de su perro (GfK 2024).", como_aplicar:"España tiene un mercado de pet food de 1.100M€ (ANFAAC 2024) pero la oferta de comida fresca y personalizada es casi inexistente fuera de Madrid y Barcelona. Una suscripción que calcule las raciones exactas según peso, edad, raza y nivel de actividad del perro y las entregue semanalmente en bolsas refrigeradas a 3-6€/día tiene diferenciación radical frente a pienso convencional.", riesgos:["Cadena de frío obligatoria: distribución refrigerada añade 2-4€ por envío al coste logístico","Formulaciones deben ser supervisadas por veterinario nutricionista: coste de asesoría 5.000-15.000€","Tasa de retención baja si el perro no acepta la comida: política de devolución clara es imprescindible"], pasos:["Contratar veterinario nutricionista para formular los menús y avalar el producto científicamente","Empezar con reparto local en radio de 30km para controlar la cadena de frío antes de escalar","Formulario de onboarding detallado: raza, peso, edad, alergias, nivel de actividad, objetivo (mantenimiento, dieta, senior)","Instagram de perros felices comiendo bien: el contenido genera conversión mejor que cualquier anuncio pagado"] },

  // ── BELLEZA & BIENESTAR ──────────────────────────────────────
  { id:47, nombre:"Clínicas de Estética con Membresía Mensual", emoji:"💆", sector:"Belleza", potencial:"Alta", dificultad:"Moderada", resumen:"Centros de estética avanzada con modelo de membresía mensual: tratamientos ilimitados de mantenimiento + precio especial en tratamientos premium.", por_que:"Ideal Image (EE.UU., laser y estética avanzada) fue adquirida por L Catterton por 500M$. MedSpa memberships es el modelo de mayor crecimiento: las membresías generan un LTV 5x superior a los clientes de pago por sesión. El mercado de medical aesthetics alcanzará 21.000M$ en EE.UU. en 2026.", como_aplicar:"España tiene 25.000 centros de estética (CAEB 2024) pero prácticamente ninguno opera con modelo de membresía. Una clínica de estética avanzada (láser, radiofrecuencia, mesoterapia) que ofrece membresía de 79-149€/mes con limpieza facial mensual ilimitada + descuento del 30% en tratamientos láser tiene ingresos recurrentes predecibles que estabilizan el negocio frente a la estacionalidad.", riesgos:["Necesitas directora técnica titulada para los tratamientos más avanzados: coste salarial 2.500-4.000€/mes","Gestión de cancelaciones y citas no asistidas con membresía es más compleja que el modelo tradicional","Inversión en equipamiento láser y radiofrecuencia: 30.000-80.000€ en aparatología"], pasos:["Auditar qué tratamientos tienen mayor recurrencia mensual en tu clínica actual y añadirlos a la membresía","Lanzar con precio fundador para los primeros 50 socios con descuento del 30% en la membresía","App o software de gestión específico para membresías: Zenoti o Fresha tienen módulo de suscripción","Diferenciador clave: check-in mensual de estado de piel para personalizar cada tratamiento incluido en la membresía"] },

  { id:48, nombre:"Barberías Premium con Experiencia", emoji:"✂️", sector:"Belleza", potencial:"Alta", dificultad:"Fácil", resumen:"Barberías de ambiente vintage o moderno con servicio lento y cuidado: corte, afeitado con navaja, masaje, bebida y experiencia completa.", por_que:"Floyd's 99 Barbershop (EE.UU.) tiene 150 locales y factura 100M$. Roosters (franquicia de barberías premium) tiene 100+ locales. El mercado de barberías en EE.UU. creció un 17% anual durante la última década. El cliente masculino paga 35-80$ por un servicio que antes era de 15$ porque compra la experiencia, no solo el corte.", como_aplicar:"España tiene 60.000 barberías pero la mayoría opera en el modelo precio bajo y rotación alta. Las barberías de experiencia en Madrid y Barcelona cobran 35-60€ y tienen lista de espera de semanas. En ciudades medianas (Salamanca, Logroño, Almería) el nicho premium no existe: el primer barbero que lo cree captura todo el mercado de hombres de 25-45 años con poder adquisitivo.", riesgos:["Dependencia del barbero estrella: si se va, se lleva el 80% de los clientes","Local bien ubicado y decorado con identidad visual fuerte: inversión de 30.000-60.000€","Capacidad limitada por naturaleza: un barbero puede hacer 4-5 servicios/hora máximo"], pasos:["Definir identidad visual clara: vintage americana, japonesa, industrial o nórdica — no mezclar estilos","Local de 50-80m² en zona de bares de copas o boutiques de moda masculina","Precio mínimo de 35€ por servicio completo (corte + barba + masaje + bebida) desde el primer día","Instagram como canal principal: el contenido visual de barbería convierte muy bien con el público objetivo"] },

  { id:49, nombre:"Spas de Baño Romano y Termas Urbanas", emoji:"🧖", sector:"Belleza", potencial:"Alta", dificultad:"Difícil", resumen:"Centros de bienestar urbanos con circuito termal, baños de contraste, sauna, hammam y zona de relajación en el centro de la ciudad.", por_que:"Well & Being (EE.UU.) y Aire Ancient Baths (española con expansión en EE.UU.) generan 10-20M$ por instalación. El mercado de spa & wellness urbano alcanzará 5.600M$ en EE.UU. en 2026. El concepto de 'baño romano moderno' tiene EBITDA del 35-45%, de los más altos del sector servicios.", como_aplicar:"Aire Ancient Baths de Barcelona, Madrid y Nueva York tiene lista de espera de semanas. Balneario de Las Arenas (Valencia) factura 8M€ anuales. En ciudades españolas de 200.000-600.000 habitantes (Zaragoza, Valladolid, Murcia, Málaga) no existe este formato. Una inversión de 500.000-1.000.000€ en una instalación premium puede generar 1.500.000-3.000.000€ anuales de facturación.", riesgos:["Inversión inicial muy alta: mínimo 500.000€ para instalaciones de calidad con piscinas termales, hammam y sauna","Requisitos técnicos muy específicos: temperatura del agua, humedad, ventilación, normativa de piscinas públicas","Dependencia de turismo en ciudades turísticas: la crisis de turismo de 2020 redujo ingresos un 70%"], pasos:["Estudio de viabilidad detallado: radio de captación, competencia, target (locales vs turistas), precio medio dispuesto a pagar","Local mínimo de 600m² con techos altos, sótano o planta baja para instalaciones hidráulicas","Arquitecto especialista en spas y termas: no cualquier arquitecto conoce los requisitos técnicos específicos","Revenue mix: entradas (60%), masajes y tratamientos (30%), privados y eventos (10%)"] },

  // ── GAMING & ENTRETENIMIENTO ──────────────────────────────────
  { id:50, nombre:"Bares de Videojuegos y Arcade", emoji:"🎮", sector:"Entretenimiento", potencial:"Alta", dificultad:"Moderada", resumen:"Bares con máquinas arcade, consolas retro, VR y pinball con modelo de entrada o membresía mensual más consumición de F&B.", por_que:"Barcade (EE.UU.) tiene 10 locales y fue valorado en 50M$. Free Play (Texas) tiene 7 locales. El mercado de 'experiential entertainment' en EE.UU. supera los 40.000M$. La generación millennial prefiere gastar en experiencias memorables compartibles en Instagram que en objetos. El ticket medio por visita es de 35-65$ con márgenes del 70% en la parte de F&B.", como_aplicar:"España tiene solo 3-4 bares de arcade de referencia en todo el país (Madrid, Barcelona). La generación de 25-40 años que creció con consolas tiene nostalgia activa por el formato retro. Un bar con 30-40 máquinas arcade en perfecto estado, cócteles temáticos y música de videojuegos en una ciudad universitaria como Salamanca, Valladolid o Pamplona puede generar 15.000-30.000€/mes.", riesgos:["Adquisición y mantenimiento de máquinas arcade en buen estado es cara y compleja (1.000-5.000€ por máquina)","Renovación constante necesaria: los clientes dejan de venir cuando ya han jugado a todo","Normativa de ruidos en locales de ocio: restricciones horarias en zonas residenciales"], pasos:["Adquirir colección inicial de 20-30 máquinas en subastas o plataformas especializadas (eBay, Arcade Belgium)","Local de 200-300m² en zona de bares con alta afluencia nocturna","Modelo de precios: entrada libre + fichas (1€/ficha o bono de 10 fichas por 8€) + consumiciones normales","Eventos temáticos semanales: torneo de Street Fighter, noche de Mario Kart, speedrun challenge"] },

  { id:51, nombre:"Escape Rooms Temáticos de Alta Producción", emoji:"🔐", sector:"Entretenimiento", potencial:"Alta", dificultad:"Moderada", resumen:"Escape rooms con producción cinematográfica, actores en vivo, efectos especiales y narrativa inmersiva de 90 minutos.", por_que:"Schell Games (EE.UU.) produce escape rooms con presupuestos de 500.000$+ por sala. The VOID (experiencias inmersivas) fue valorada en 100M$. El mercado global de escape rooms supera 2.000M$ con 50.000 instalaciones. El ticket medio por experiencia premium es de 30-50€/persona con grupos de 4-8 personas, generando 300-500€ por experiencia de 90 minutos.", como_aplicar:"España tiene 1.200 escape rooms (segundo país europeo por densidad) pero el 95% son de baja producción. Los clientes ya conocen el formato básico y buscan mayor inmersión. Un escape room con actores en vivo, efectos especiales profesionales (niebla, efectos de sonido envolvente, pantallas), decorados cinematográficos y narrativa de 90 minutos en ciudad de 300.000+ habitantes tiene 0 competencia directa.", riesgos:["Inversión alta por sala: producción premium cuesta 80.000-200.000€ vs 15.000-30.000€ de un escape room estándar","Capacidad limitada: 3-4 grupos por sala al día máximo, limitando el potencial de ingresos","Desgaste del contenido: en 12-18 meses los clientes frecuentes ya han jugado todo y quieren experiencia nueva"], pasos:["Diseñar narrativa antes de construir: contratar guionista de teatro o cine para la historia y los puzles","Socio de producción: empresa de efectos especiales o atrezzo teatral para la construcción de decorados","Precio diferenciado: 28€/persona grupo pequeño, 24€/persona grupo >6, experiencia privada VIP 350€","Sistema de reservas online con gestión de grupos y venta de packs de cumpleaños desde el día 1"] },

  // ── FINANZAS ─────────────────────────────────────────────────
  { id:52, nombre:"Neo-broker de Inversión para Millennials", emoji:"📈", sector:"Finanzas", potencial:"Media", dificultad:"Difícil", resumen:"Plataforma de inversión en acciones, ETFs y criptomonedas con educación integrada, interfaz UX y sin comisiones.", por_que:"Robinhood alcanzó 22 millones de usuarios en EE.UU. Public.com fue valorada en 1.200M$. El 78% de millennials americanos invierte activamente vs 43% de generaciones anteriores. Las comisiones cero + app bien diseñada democratizaron la inversión: el saldo medio de cuenta pasó de 15.000$ a 5.000$ (más cuentas, menor tamaño).", como_aplicar:"España tiene el ratio de hogares inversores en bolsa más bajo de la UE: solo el 18% vs 55% en EE.UU. Indexa Capital (española) gestiona 1.500M€ con 60.000 clientes. Hay espacio para una plataforma centrada en millennials españoles con educación financiera integrada (aprende mientras inviertes), interfaz muy intuitiva y sin comisiones de custodia. La obligación de invertir en planes de pensiones por la crisis de la Seguridad Social crea urgencia.", riesgos:["Regulación CNMV y MiFID II es extremadamente exigente: licencia como Empresa de Servicios de Inversión cuesta 500.000€+","Competencia feroz de Trade Republic (alemán), eToro e Interactive Brokers que ya operan en España","Capital de riesgo necesario: este negocio requiere mínimo 5-10M€ de inversión inicial para ser viable"], pasos:["Este negocio requiere inversión de venture capital: necesitas crear deck, validar modelo y levantar ronda seed de 2-5M€","Alternativa más accesible: plataforma educativa sobre inversión (no gestión de dinero) que sí es regulatoriamente más simple","Validar con lista de espera: crea landing page y mide cuántas personas dan su email antes de invertir en desarrollo","Licencia CIF o agente vinculado a una entidad ya regulada para operar legalmente sin licencia propia"] },

  { id:53, nombre:"Microseguros para Economía Gig", emoji:"🛡️", sector:"Finanzas", potencial:"Alta", dificultad:"Difícil", resumen:"Seguros flexibles por horas, días o semanas para riders, freelancers y trabajadores de plataformas digitales sin cobertura fija.", por_que:"Lemonade (EE.UU.) alcanzó 1.600M$ de valoración en su IPO. Cuvva (UK, seguros de coche por horas) fue adquirida por Direct Line. El 36% de trabajadores en EE.UU. trabaja en la economía gig sin acceso a seguros corporativos (McKinsey 2024). Los microseguros tienen tasas de conversión 3x superiores en mobile que los seguros anuales convencionales.", como_aplicar:"España tiene 600.000 riders de delivery y 1 millón de freelancers activos (Malt 2024), la mayoría sin cobertura de accidentes laborales adecuada para sus horas de trabajo real. Un seguro de accidente activable por app de 0.50-2€/hora activa (solo pagas cuando trabajas) tiene propuesta clara para Glovo y Uber Eats riders y para freelancers que van a reuniones.", riesgos:["Licencia de mediador de seguros o aseguradora propia: coste regulatorio de 200.000-1.000.000€","Riesgo actuarial: el perfil de riesgo de riders en ciudad es muy distinto al de oficinistas: pricing complejo","Dependencia de plataformas: si Glovo cambia su política y ofrece seguro propio, el mercado desaparece"], pasos:["Modelo de distribución: B2B2C a través de las propias plataformas (Glovo, Uber, Malt) como socio de distribución","Acuerdo con aseguradora ya regulada como underwriter para poder operar sin licencia propia en la primera fase","Producto mínimo viable: seguro de accidente laboral activable por app a 0.80€/hora activa","Validar demanda: encuesta a 500 riders antes de invertir en desarrollo de la plataforma tecnológica"] },

  // ── MOVILIDAD ────────────────────────────────────────────────
  { id:54, nombre:"Garajes de Carga para Vehículos Eléctricos", emoji:"⚡", sector:"Movilidad", potencial:"Alta", dificultad:"Moderada", resumen:"Red de puntos de carga rápida y ultrarrápida para coches eléctricos en garajes de comunidades y zonas comerciales.", por_que:"EVgo (EE.UU.) fue valorada en 2.700M$ en su cotización en Nasdaq. ChargePoint tiene 73.000 puntos de carga y vale 1.400M$. España venderá 1 millón de coches eléctricos anuales en 2030 (ANFAC) pero tiene solo 18.000 puntos de carga públicos vs 500.000 necesarios. La escasez de carga es el principal freno a la adopción del vehículo eléctrico.", como_aplicar:"El 74% de propietarios de VE en España carga en casa o en el trabajo (IDAE 2024) pero el 35% vive en piso sin posibilidad de instalar cargador privado. Un negocio que instala cargadores en garajes comunitarios con modelo de sharing (la comunidad tiene acceso gratuito, los de fuera pagan) y cobra por el hardware + mantenimiento + % de la electricidad tiene propuesta clara en cualquier ciudad española.", riesgos:["Inversión en infraestructura eléctrica del edificio: refuerzo de potencia cuesta 5.000-20.000€ por garaje","Regulación de instalaciones eléctricas en garajes comunitarios: necesitas instalador autorizado por industria","Competencia de Endesa, Iberdrola y Repsol que tienen programas propios de instalación en comunidades"], pasos:["Especialización: garajes de comunidades de propietarios con cargadores a coste 0 para la comunidad","Modelo de negocio: instalas gratis el hardware a cambio de gestión exclusiva del punto de carga durante 10 años","Ingresos: cargo 0.30-0.45€/kWh a usuarios externos vs 0.15€/kWh de coste eléctrico (margen 50-60%)","Canal: administradores de fincas con incentivos de referido para acceso masivo a comunidades"] },

  { id:55, nombre:"Suscripción de Patinetes y Bicicletas para Empresas", emoji:"🛴", sector:"Movilidad", potencial:"Media", dificultad:"Moderada", resumen:"Servicio de movilidad eléctrica por suscripción mensual para empleados de empresas: patinete o bici eléctrica + seguro + mantenimiento incluido.", por_que:"Swapfiets (Países Bajos) tiene 250.000 suscriptores en Europa a 20-25€/mes y fue valorada en 300M$. Vélib (París) tiene 300.000 usos diarios. Las empresas en EE.UU. ofrecen beneficios de movilidad sostenible como complemento al salario: el 34% de empleados prefiere beneficios de movilidad a parking gratuito (encuesta Commuter Benefits 2024).", como_aplicar:"La Ley de Movilidad Sostenible española de 2023 incentiva el commuting en bici con deducciones fiscales. El beneficio de movilidad para empleados puede articularse como retribución flexible con ventajas fiscales. Un servicio B2B a 25-45€/empleado/mes (patinete eléctrico + seguro + mantenimiento + recogida en avería en 2h) vendido a empresas de 50-500 empleados tiene ciclo de venta corto.", riesgos:["Capital intensivo: cada patinete o bici eléctrica cuesta 300-800€ de inversión inicial con vida útil de 18-24 meses","Mantenimiento y vandalismo en uso diario intensivo: coste operativo del 15-25% de los ingresos","Competencia de Lime y Bolt que ofrecen opciones de empresa a precios similares"], pasos:["Empezar con B2B exclusivamente: empresas que pagan puntualmente, más fácil gestión de flota","Paquete inicial: 20 patinetes eléctricos de calidad (Segway Ninebot, Xiaomi Pro) + 2 de repuesto operativos siempre","App propia o uso de Joyride (plataforma de gestión de flotas) para control en tiempo real","Propuesta de valor fiscal: 'beneficio de movilidad exento de IRPF hasta 1.500€/año para el empleado'"] },

  // ── SALUD ────────────────────────────────────────────────────
  { id:56, nombre:"Lavanderías Self-Service Premium", emoji:"🧺", sector:"Servicios", potencial:"Alta", dificultad:"Fácil", resumen:"Lavanderías completamente automatizadas 24/7 con app de reservas, pago sin efectivo, secadoras industriales y marca premium.", por_que:"Wash Club (EE.UU.) y SpinLaundry tienen valoraciones de 50-100M$. El modelo de lavandería premium genera ingresos por m² 3x superiores a la lavandería tradicional. El ticket medio sube de 4€ a 12-18€ cuando la experiencia es premium (espacio limpio, máquinas nuevas, wifi, café, app). El 35% de hogares urbanos jóvenes no tiene lavadora propia en España (INE 2024).", como_aplicar:"España tiene 10.000 lavanderías de las cuales el 90% son antiguas, sucias y sin diferenciación. Las ciudades universitarias (Granada, Salamanca, Murcia, Alicante) con alta densidad de estudiantes y jóvenes profesionales son el target perfecto. Una inversión de 60.000-100.000€ en un local de 80-120m² bien ubicado puede generar 8.000-15.000€/mes con márgenes del 50-60%.", riesgos:["Inversión inicial en maquinaria industrial (lavadoras Miele o Electrolux de 8kg+): 3.000-8.000€ por máquina","Mantenimiento constante y urgente: una máquina rota un viernes noche destruye la experiencia del cliente","Ubicación absolutamente crítica: el local necesita estar en un radio de 500m de alta densidad de target"], pasos:["Análisis geoespacial antes de firmar: contar estudiantes y jóvenes en radio de 500m con Google Maps + INE","Leasing de maquinaria en lugar de compra: reduce la inversión inicial un 60% y transfiere el riesgo de obsolescencia","App propia o integración con GreenHalo o SpeedQueen Connect para reservas y pago sin efectivo","Diseño diferenciador: planta con luz natural, plantas, buena música, zona de espera cómoda, wifi de 1Gb"] },

  // ── ALIMENTACIÓN SALUDABLE ────────────────────────────────────
  { id:57, nombre:"Farmacias de Suplementos Personalizados", emoji:"💊", sector:"Salud", potencial:"Alta", dificultad:"Moderada", resumen:"Servicio de suplementación mensual personalizada según análisis de sangre, genética, objetivos de salud y estilo de vida.", por_que:"Care/of (EE.UU.) fue adquirida por Bayer por 225M$ con 2 millones de suscriptores. Ritual tiene 500.000 suscriptoras y factura 100M$. El mercado de suplementos personalizados alcanzará 1.200M$ en 2026. El consumidor ya no quiere el multivitamínico genérico: quiere exactamente lo que necesita su cuerpo.", como_aplicar:"España tiene un mercado de suplementos de 850M€ que crece al 8% anual (AFEPADI 2024) pero la mayoría son productos genéricos de eroski o Amazon. Un servicio que combina cuestionario de salud online (15 min) + análisis de sangre opcional + recomendación personalizada de 3-5 suplementos + entrega mensual en pastillero organizado por día a 39-79€/mes tiene diferenciación enorme.", riesgos:["Regulación de venta de complementos alimenticios es estricta: registro en AESAN y etiquetado específico","Si incluyes análisis de sangre necesitas médico o farmacéutico en el equipo: coste adicional significativo","Competencia de marcas farmacéuticas (Bayer, Roche) con presupuestos de marketing millonarios"], pasos:["Empezar sin análisis de sangre: solo cuestionario de salud validado por nutricionista","Acuerdo de distribución con laboratorio de suplementos certificado que fabrique con tu marca","Caja mensual con pastillero personalizado: la presentación es un diferenciador que genera retención y fotos de Instagram","Canal inicial: influencers de salud y fitness para captación con código de descuento trackeable"] },

  { id:58, nombre:"Clínicas de Longevidad y Anti-Aging", emoji:"🔬", sector:"Salud", potencial:"Media", dificultad:"Difícil", resumen:"Centros médicos que optimizan la salud con análisis avanzados de biomarcadores, protocolos personalizados de longevidad y medicina preventiva.", por_que:"Human Longevity Inc. (EE.UU.) factura 50M$+ con chequeos de longevidad a 25.000$/año. Function Health (Peter Attia) tiene 100.000 miembros a 499$/año. El mercado de longevity wellness alcanzará 44.000M$ en 2030. La clase alta ya no quiere solo 'no enfermar', quiere 'vivir más y mejor': willingness to pay altísima.", como_aplicar:"España tiene los médicos de cabecera más sobrecargados de Europa (2.000 pacientes por médico) y la sanidad privada es cara pero básica. Una clínica de longevidad en Madrid o Barcelona que ofrece análisis de 50+ biomarcadores (VO2Max, DEXA, análisis de microbioma, biomarcadores inflamatorios) + protocolo personalizado de optimización a 1.500-5.000€/año tiene mercado inmediato entre profesionales de alta renta.", riesgos:["Equipo médico de alta cualificación: especialistas en medicina antienvejecimiento son escasos y caros en España","Regulación sanitaria muy estricta para clínicas médicas: certificación de centro sanitario por comunidad autónoma","Riesgo de posicionamiento: diferenciarse de la medicina alternativa o el curanderismo es crítico para la credibilidad"], pasos:["Médico director con formación en medicina antienvejecimiento como cofundador y cara del negocio (imprescindible)","Equipamiento inicial: densitometría DEXA, prueba de esfuerzo con VO2Max, equipos de análisis de sangre avanzado","Primer producto: 'Chequeo de longevidad completo' a 800-1.500€ como punto de entrada con posterior suscripción anual","Canal: eventos privados para ejecutivos y directivos a través de clubes exclusivos y family offices"] },

  // ── EVENTOS ──────────────────────────────────────────────────
  { id:59, nombre:"Experiencias Gastronómicas Clandestinas", emoji:"🍽️", sector:"Entretenimiento", potencial:"Alta", dificultad:"Fácil", resumen:"Cenas secretas en localizaciones únicas (tejados, bodegas, museos cerrados) organizadas por chefs invitados con lista de espera exclusiva.", por_que:"Dinner in the Sky (experiencias elevadas) opera en 45 países con precios de 200-500$ por persona. Ghetto Gastro (NY) genera 5M$+ con eventos culinarios experienciales. El mercado de experiencias gastronómicas premium crece al 18% anual. El millennials gasta el 32% de su presupuesto de ocio en experiencias memorables (Eventbrite 2024).", como_aplicar:"España tiene la mejor cultura gastronómica del mundo pero pocos operadores de experiencias clandestinas. Madrid y Barcelona tienen varios pero ciudades como Sevilla, Valencia, Bilbao o San Sebastián tienen cero oferta. Una cena mensual para 20-30 personas en localización única (tejado con vistas, bodega histórica, museo cerrado al público) con chef invitado a 80-150€/persona genera 2.000-4.500€ de facturación por evento.", riesgos:["Permisos para eventos en espacios no habituales pueden ser complejos y tardar meses en obtenerse","Dependencia de chefs invitados: si un chef cancela, el evento colapsa sin sustituto de calidad","Marketing por escasez solo funciona si la experiencia es genuinamente memorable: una mala noche destruye el boca a boca"], pasos:["Empezar con un evento mensual de 20 personas en tu red de contactos para validar formato, precio y calidad antes de escalar","Acuerdo con chef local de buen nivel (no necesitas estrella Michelin al principio) con fee fijo de 500-800€","Localización: acuerdo con propietario de tejado, bodega o sala privada a coste bajo o gratuito a cambio de visibilidad","Lista de espera en Typeform como herramienta de marketing de escasez + comunidad de WhatsApp VIP"] },

  { id:60, nombre:"Eventos Corporativos de Team Building Inmersivo", emoji:"🎯", sector:"Entretenimiento", potencial:"Alta", dificultad:"Fácil", resumen:"Experiencias de team building para empresas que van más allá del karting o el paintball: cocina, teatro, impro, escape room privado, olimpiadas.", por_que:"Teambonding (EE.UU.) factura 30M$+ con experiencias de team building. The Go Game genera 10M$ con actividades de ciudad. El mercado de team building corporativo alcanzará 30.000M$ en 2027. El presupuesto por evento corporativo en EE.UU. es de 150-300$ por persona, el doble que en España.", como_aplicar:"Las empresas españolas gastan 500M€ anuales en team building pero la oferta es básica y anticuada (karting, paintball, cenas en restaurante). Un proveedor de experiencias inmersivas y memorables (cocinar con chef estrella, taller de impro teatral, olimpiadas en finca rural, ruta de senderismo con picnic) para grupos de 15-100 personas a 80-200€/persona tiene diferenciación total.", riesgos:["Estacionalidad marcada: 80% de los eventos se concentran en octubre-diciembre y mayo-junio","Dependencia de proveedores externos (chefs, instalaciones, guías) cuya disponibilidad no controlas","Margen se comprime con grupos pequeños: por debajo de 20 personas la actividad no es rentable"], pasos:["Catálogo de 5-8 experiencias concretas con precio cerrado por persona, sin presupuestos a medida inicialmente","Canal B2B: LinkedIn Ads a directores de RRHH y responsables de comunicación interna de empresas de 50-500 empleados","Acuerdo con 3-5 proveedores exclusivos (chef, finca, sala de teatro) con disponibilidad garantizada para tu cartera","Testimoniales en video de los eventos: el comprador de team building siempre busca referencias visuales"] },

  // Trends 61-100
  { id:61, nombre:"Consultoría de IA para PYMEs", emoji:"🤖", sector:"Tech", potencial:"Alta", dificultad:"Fácil", resumen:"Servicio de implementación de herramientas de IA en pequeñas empresas: automatización, chatbots, análisis de datos y formación del equipo.", por_que:"El 89% de las PYMEs americanas ya usa alguna herramienta de IA (McKinsey 2024) vs el 34% de las europeas. Las consultoras de IA especializadas en PYMEs facturan 500.000-5M$ anuales con equipos de 5-15 personas. El mercado de AI consulting para SMB alcanzará 15.000M$ en 2027.", como_aplicar:"Solo el 12% de las PYMEs españolas ha implementado alguna herramienta de IA (ONTSI 2024) a pesar de que el 78% declara interés. Un consultor que implementa ChatGPT para atención al cliente, Make para automatizar procesos y Midjourney para el marketing visual de una PYME en 2 semanas a 3.000-8.000€ tiene argumento de ROI inmediato.", riesgos:["El servicio escala mal: cada implementación requiere trabajo manual del consultor","Competencia de las propias plataformas de IA que ofrecen onboarding gratuito","Conocimiento que se democratiza rápidamente: en 2 años las PYMEs lo harán solas"], pasos:["Especializarse en un sector vertical: IA para restaurantes, IA para clínicas, IA para despachos de abogados","Productizar el servicio: paquete fijo de 2 semanas + 2.990€ con entregables concretos, no consultoria abierta","Canal: LinkedIn con contenido de casos de éxito reales mostrando antes/después del cliente","Upsell: mantenimiento mensual de 300-500€/mes para actualizaciones y nuevas implementaciones"] },

  { id:62, nombre:"Escuelas de Cocina para Adultos", emoji:"👨‍🍳", sector:"Entretenimiento", potencial:"Alta", dificultad:"Fácil", resumen:"Academias de cocina para adultos con clases presenciales temáticas, cenas con los platos cocinados y formato social.", por_que:"Sur La Table (EE.UU.) tiene 130 escuelas de cocina y genera 300M$. America's Test Kitchen tiene 1.8M de suscriptores de pago. El mercado de clases de cocina alcanzará 2.700M$ en EE.UU. en 2026. La cocina es el hobby de mayor crecimiento en adultos de 30-55 años: el 44% declara que 'aprender a cocinar mejor' está en su lista de propósitos anuales.", como_aplicar:"En España hay pocas escuelas de cocina para adultos con formato social (cocinar + cenar juntos). Le Cordon Bleu Madrid y Gasma son para profesionales. El adulto de 30-55 años que quiere aprender cocina japonesa, pasta fresca, pastelería francesa o paella auténtica en un formato de tarde del sábado (4h, cocinar + comer + vino) a 65-95€/persona tiene mercado claro en cualquier ciudad de más de 100.000 habitantes.", riesgos:["Necesitas cocina equipada con 8-12 puestos de trabajo: inversión de 30.000-60.000€ o alquiler de cocina existente","Captación constante necesaria: los clientes repiten 2-3 veces al año como máximo","Chef instructor debe tener carisma pedagógico, no solo habilidad culinaria: perfil difícil de encontrar"], pasos:["Empezar alquilando cocina de restaurante en sus horarios de cierre (lunes noche, domingo mañana)","Formato estándar de éxito: 2-3 horas de cocina en grupos de 8-12 personas + 1h de cena con lo cocinado + vino","Temáticas de mayor conversión: japonesa, pasta italiana, coctelería, sushi, repostería francesa","Canal: eventos en Eventbrite + grupos de Facebook de ocio en tu ciudad + acuerdos con agencias de regalos"] },

  { id:63, nombre:"Centros de Bienestar para Empresas en Remoto", emoji:"🏔️", sector:"Servicios", potencial:"Alta", dificultad:"Moderada", resumen:"Espacios rurales de trabajo en remoto con coworking, naturaleza, actividades de bienestar y desconexión digital para equipos de empresas.", por_que:"Outsite (EE.UU.) tiene 30 propiedades en 15 países para nómadas digitales. Selina (remote year) tiene 150 propiedades globales y cotiza en Nasdaq. El 68% de empresas americanas planea organizar un 'company retreat' anual (Harvard Business Review 2024) con presupuesto medio de 1.500-3.000$/empleado.", como_aplicar:"El trabajo en remoto ha creado una demanda enorme de 'retreats' empresariales de 3-5 días donde el equipo trabaja juntos en un entorno natural. España rural tiene propiedades hermosas en Gredos, Picos de Europa, Pirineos o Sierra Nevada que podrían reconvertirse. Un retiro de empresa de 4 días para 10-20 personas con coworking equipado, actividades de naturaleza, chef y bienestar a 300-500€/persona/día genera 12.000-40.000€ por retiro.", riesgos:["Inversión en reforma de la propiedad: coworking equipado + habitaciones confortables + espacios comunes: 100.000-300.000€","Estacionalidad: meses de invierno tienen ocupación muy baja en destinos de montaña","Logística de transporte desde ciudades: accesibilidad es determinante para la decisión de compra"], pasos:["Empezar gestionando la propiedad de un tercero (hotel rural, finca) en modelo de revenue sharing para validar el modelo sin inversión","Producto mínimo viable: 4 días/3 noches para 10-15 personas con programa fijo de trabajo + naturaleza + bienestar","Canal B2B: LinkedIn targeting a CEOs y directores de RRHH de startups y empresas tech en remoto","Alianza con plataformas de team building para distribución de tu espacio como venue exclusivo"] },

  { id:64, nombre:"Plataforma de Freelancers Verificados por Sector", emoji:"💼", sector:"Tech", potencial:"Alta", dificultad:"Moderada", resumen:"Marketplace de talento freelance con verificación de portfolio, pruebas técnicas y reputación garantizada, especializado por sector.", por_que:"Toptal (EE.UU.) cobra 20.000-40.000$/mes a empresas por talento tech verificado. el modelo 'elite network' tiene márgenes del 40% vs 10-15% de plataformas genéricas como Upwork. Malt (francés, el Toptal europeo) fue valorado en 600M€ con 500.000 freelancers.", como_aplicar:"Malt opera en España pero es generalista. Un marketplace vertical de freelancers para un sector específico (ej: solo desarrolladores de IA, solo diseñadores UX, solo especialistas en SEO) con proceso de vetting riguroso y garantía de calidad del resultado tiene diferenciación clara y puede cobrar una comisión del 20-25% vs 10% de Malt.", riesgos:["Efecto de red bilateral: necesitas freelancers y clientes simultáneamente","Proceso de vetting caro: 3-5 horas por freelance para verificar portfolio, hacer prueba técnica y entrevistar","Competencia de Toptal con 10 años de ventaja y presupuesto de marketing millonario"], pasos:["Elegir nicho muy específico: developers de IA es el más demandado y donde el cliente paga más","Lanzar con 50 freelancers verificados manualmente antes de abrir a clientes: la calidad del supply es todo","Garantía diferenciadora: 'Si en 48h no estás satisfecho con el freelance asignado, te asignamos otro gratuitamente'","Canal de clientes: LinkedIn Ads a CTOs y directores de tecnología de startups Series A/B"] },

  { id:65, nombre:"Estaciones de Carga de Mochilas Solares", emoji:"🌞", sector:"Sostenibilidad", potencial:"Media", dificultad:"Fácil", resumen:"Red de puntos de carga solar gratuita para dispositivos móviles en playas, parques y zonas turísticas financiada con publicidad.", por_que:"SolarCity (adquirida por Tesla) y Strawberry Energy (Serbia) han demostrado que las estaciones de carga solar con publicidad son rentables en espacios públicos. En EE.UU., Soofa instala muebles urbanos con carga solar y pantallas publicitarias en 300 ciudades con ingresos de 5.000-15.000$/mes por unidad.", como_aplicar:"España recibe 85 millones de turistas anuales que pasan horas en playas y parques necesitando cargar el móvil. Un negocio que instala estaciones de carga solar gratuita en ayuntamientos a cambio de gestionar la publicidad digital en las pantallas tiene coste de instalación de 3.000-6.000€ por estación y genera 800-2.000€/mes en publicidad por ubicación.", riesgos:["Negociación con ayuntamientos es lenta y burocrática: ciclo de venta de 6-18 meses","Mantenimiento y vandalismo en instalaciones al aire libre: coste operativo del 20-30%","Dependencia de inversión publicitaria local que puede ser volátil"], pasos:["Diseñar prototipo de estación con paneles solares (300W), batería de almacenamiento y 6-8 puertos USB-C","Presentar a 3-5 ayuntamientos de municipios turísticos con modelo de 'sin coste para el ayuntamiento'","Contratos de publicidad con anunciantes locales (restaurantes, hoteles, tiendas) a 300-600€/mes por panel","Escalar a 50-100 estaciones en 2-3 municipios antes de buscar financiación para expansión nacional"] },

  { id:66, nombre:"Academias de Deporte Adaptado", emoji:"♿", sector:"Fitness & Salud", potencial:"Alta", dificultad:"Moderada", resumen:"Centros de entrenamiento físico y actividad deportiva especializados en personas con discapacidad física o diversidad funcional.", por_que:"Adaptive Sports Foundation (EE.UU.) crece al 35% anual. El mercado de fitness adaptado alcanzará 2.100M$ en 2026. En EE.UU., el 26% de la población adulta tiene algún tipo de discapacidad pero solo el 8% practica deporte regularmente (CDC 2024). Las empresas de seguros americanas pagan las sesiones como rehabilitación preventiva.", como_aplicar:"España tiene 4,3 millones de personas con discapacidad (IMSERSO 2024) y una oferta deportiva adaptada prácticamente inexistente fuera de los centros de la ONCE y algunos polideportivos municipales con horarios muy limitados. Un centro de deporte adaptado con equipamiento específico (máquinas de accesibilidad, piscina de profundidad variable, staff formado) puede generar ingresos por cuotas + seguros + convenios con mutuas.", riesgos:["Inversión en adaptaciones del local y equipamiento específico: 50.000-150.000€","Formación especializada del personal: pocos fisioterapeutas y entrenadores tienen formación en deporte adaptado","Ciclo de ventas largo para convenios con mutuas y seguros médicos: 6-18 meses"], pasos:["Convenio con universidad de fisioterapia o INEF para prácticas: reduce coste de personal especializado","Local adaptado: rampa, baños amplios, vestuarios accesibles, equipamiento de baja resistencia y poleas adaptadas","Contacto directo con trabajadores sociales de hospitales y centros de rehabilitación como canal de derivación","Modelo de ingresos mixto: cuotas mensuales + facturación a mutuas laborales + convenios con ayuntamientos"] },

  { id:67, nombre:"Servicios de Doula y Acompañamiento en Maternidad", emoji:"👶", sector:"Salud", potencial:"Alta", dificultad:"Fácil", resumen:"Acompañamiento profesional durante el embarazo, parto y postparto: apoyo emocional, información, presencia en el parto y ayuda en lactancia.", por_que:"DONA International (EE.UU.) tiene 15.000 doulas certificadas. Las madres que tienen doula tienen un 50% menos de cesáreas, 60% menos de epidurales y estancias hospitalarias un 25% más cortas (Cochrane Review 2023). El mercado de servicios de doula alcanzará 3.000M$ en EE.UU. en 2027. El precio medio es de 1.500-3.000$ por embarazo completo.", como_aplicar:"España tiene menos de 500 doulas certificadas para 360.000 partos anuales. La medicalización excesiva del parto (el 24% son cesáreas vs 15% recomendado por la OMS) crea demanda de alternativas humanizadas. Una doula a 800-2.500€ por proceso completo (preparto + parto + postparto) con certificación DONA o similares tiene mercado creciente especialmente entre madres de 30-40 años de clase media-alta.", riesgos:["No hay regulación oficial de doulas en España: cualquiera puede llamarse doula, lo que daña la credibilidad del sector","El parto puede ser impredecible: disponibilidad 24h en las semanas cercanas al parto es emocionalmente agotadora","Conflicto potencial con el personal médico del hospital que puede ver la presencia de la doula como intrusión"], pasos:["Certificación internacional reconocida: DONA International, Association of Labor Assistants and Childbirth Educators","Definir paquetes claros: solo postparto (más fácil para empezar), preparto o proceso completo","Captación: grupos de Facebook de madres primerizas, cursos de preparación al parto y ginecólogos como referidores","Supervisión legal: la doula no realiza funciones médicas; protocolo de actuación claro para evitar conflictos con el hospital"] },

  { id:68, nombre:"Plataforma de Subvenciones con IA", emoji:"📋", sector:"Tech", potencial:"Alta", dificultad:"Moderada", resumen:"Herramienta que usa IA para identificar automáticamente las subvenciones y ayudas públicas para las que es elegible una empresa y gestiona la solicitud.", por_que:"Grantable (EE.UU.) usa IA para redactar solicitudes de subvenciones para ONG y factura 2M$+. Instrumentl tiene 3.000+ organizaciones clientes a 179$/mes. España distribuye 30.000M€ anuales en subvenciones y ayudas públicas (BDNS 2024) de los cuales el 40% no se solicita por desconocimiento o complejidad.", como_aplicar:"Las PYMEs españolas dejan de recibir 12.000M€ anuales en ayudas a las que tendrían derecho por falta de información y complejidad de los trámites (CEOE 2024). Una plataforma a 49-99€/mes que analiza el perfil de la empresa y envía alertas de subvenciones disponibles en su sector, comunidad autónoma y tamaño tiene valor inmediato y clarísimo: 'Por 50€/mes te avisamos de las ayudas que te pueden dar 50.000€'.", riesgos:["Base de datos de subvenciones requiere actualización diaria: proceso técnico complejo con scraping de múltiples fuentes oficiales","El proceso de solicitud real sigue requiriendo trabajo humano: el software solo identifica, no tramita automáticamente","Monetización del éxito difícil: la empresa recibe la subvención meses después de haberla solicitado, el coste del software parece alto mientras espera"], pasos:["Construir scraper de la BDNS (Base de Datos Nacional de Subvenciones) y BOE para actualización diaria de convocatorias","Algoritmo de matching: empresa introduce SIC code, tamaño, comunidad autónoma, antigüedad → lista de ayudas prioritarias","Lanzar con 50 empresas beta a 29€/mes: el precio bajo facilita la adopción sin objeción","Modelo premium: además del software (49€/mes), servicio de tramitación por gestor humano (cobrar % de la subvención conseguida)"] },

  { id:69, nombre:"Servicios de Organización del Hogar (Home Organization)", emoji:"🏡", sector:"Servicios", potencial:"Alta", dificultad:"Fácil", resumen:"Servicio profesional de organización, clasificación y optimización del espacio del hogar, inspirado en el método Marie Kondo.", por_que:"The Home Edit (EE.UU.) tiene 8 millones de seguidores en Instagram, serie en Netflix y fue adquirida por Clea y Joanna por un valor de decenas de millones. NAPO (National Association of Productivity and Organizing Professionals) tiene 3.500 miembros. El servicio en EE.UU. cuesta 50-150$/hora con sesiones de 6-8 horas: 300-1.200$ por habitación.", como_aplicar:"España descubrió el método KonMari con el programa de Netflix de Marie Kondo y la demanda explotó, pero hay poquísimos profesionales certificados. El contexto urbano español (pisos pequeños, mucho acúmulo) crea necesidad real. Un organizador profesional a 60-90€/hora con sesiones de 4-6 horas puede generar 3.000-6.000€/mes con solo 3-4 clientes semanales.", riesgos:["Servicio de tiempo: solo puedes hacer 3-4 sesiones semanales como autónomo antes de necesitar contratar","El cliente puede sentirse juzgado o invadido en su espacio íntimo: habilidades sociales fundamentales","Repetición baja: un cliente hace 1-2 sesiones y no vuelve (salvo si ofreces servicio de mantenimiento)"], pasos:["Certificación KonMari o NAPO para credibilidad y metodología probada","Fotos del antes/después de cada proyecto (con permiso) para Instagram: el visual del orden y el caos transformado convierte perfectamente","Definir servicio estándar: 'Sesión de 4h para un dormitorio o sala de estar a 240€'","Canal inicial: grupos de 'minimalismo', 'orden en casa' y 'decoración' en Facebook e Instagram + Wallapop (ironía útil)"] },

  { id:70, nombre:"Clínicas de Sueño y Optimización del Descanso", emoji:"😴", sector:"Salud", potencial:"Alta", dificultad:"Moderada", resumen:"Centros especializados en el diagnóstico y tratamiento de problemas del sueño: apnea, insomnio, fatiga crónica, con tecnología wearable.", por_que:"Eight Sleep (EE.UU.) fue valorada en 500M$. Somna Therapeutics factura 50M$+ tratando la apnea del sueño. El mercado de sleep health alcanzará 114.000M$ en 2025 (Global Wellness Institute). El insomnio cuesta a las empresas americanas 411.000M$ anuales en productividad perdida (RAND Corporation 2023).", como_aplicar:"El 25% de los españoles tiene problemas crónicos de sueño (Sociedad Española de Neurología 2024) y el tiempo de espera para una unidad del sueño en la sanidad pública es de 12-18 meses. Una clínica privada que combina polisomnografía domiciliaria (diagnóstico en casa con dispositivo prestado), consulta con especialista en sueño y protocolo de 8 semanas basado en CBT-I (terapia cognitivo-conductual para el insomnio) a 600-1.500€ por proceso completo tiene mercado inmediato.", riesgos:["Médico especialista en medicina del sueño es imprescindible: escasez en España y coste salarial alto","Equipamiento de polisomnografía domiciliaria: 2.000-5.000€ por dispositivo con logística de envío y recogida","Competencia de las Unidades del Sueño hospitalarias privadas ya establecidas en grandes ciudades"], pasos:["Primer producto: evaluación online del sueño (Pittsburgh Sleep Quality Index + actigrafía wearable 2 semanas) a 149€","Protocolo CBT-I online de 8 sesiones con psicólogo especializado: 400€ (puede hacerse remoto desde cualquier lugar de España)","Derivar los casos que necesiten polisomnografía completa a clínica socia hasta tener volumen para equipo propio","Canal: empresas de salud corporativa y médicos de cabecera con lista de espera como prescriptores"] },

  { id:71, nombre:"Supermercados de Productos Sin Gluten y Sin Alérgenos", emoji:"🌾", sector:"Food & Drink", potencial:"Media", dificultad:"Moderada", resumen:"Tiendas especializadas exclusivamente en alimentación sin gluten, sin lactosa, sin azúcar y sin los 14 alérgenos principales.", por_que:"Aldi y Whole Foods tienen secciones de 'free from' que generan el 15-20% de sus ingresos en EE.UU. El mercado global de alimentos sin gluten alcanzará 12.000M$ en 2027. En EE.UU., el 1% tiene celiaquía, pero el 30% compra gluten-free por elección (SPINS 2024). El precio premium es del 40-100% sobre el equivalente convencional con márgenes superiores al 35%.", como_aplicar:"España tiene 450.000 celíacos diagnosticados (FACE 2024) y más de 3 millones de personas con intolerancia al gluten. El problema actual: los celíacos tienen que comprar en tiendas especializadas caras o buscar el pequeño rincón de Mercadona. Una tienda de 80-120m² con todo el surtido sin gluten a un precio razonable, certificada sin contaminación cruzada, en cualquier ciudad de +100.000 habitantes tiene clientela fidelísima y alto ticket medio.", riesgos:["Certificación de libre contaminación cruzada es cara y requiere auditorías regulares","Logística de aprovisionamiento compleja: proveedores de productos sin alérgenos son escasos y caros","Ticket medio alto (35-60€) pero frecuencia de visita baja (1-2 veces por semana máximo) limita el volumen"], pasos:["Certificación con AGRUCELAC o ASPROCESE para acreditar la ausencia de contaminación cruzada","Surtido inicial de 500-800 referencias sin gluten, sin lactosa y sin azúcar de los mejores proveedores nacionales","Foro o grupo de Facebook de celíacos locales como canal de captación: comunidad muy activa y leal","Taller mensual de cocina sin gluten para fidelizar y generar contenido para redes sociales"] },

  { id:72, nombre:"Agencias de Marketing de Influencers Locales", emoji:"📱", sector:"Tech", potencial:"Alta", dificultad:"Fácil", resumen:"Agencia especializada en conectar microinfluencers locales (5.000-100.000 seguidores) con marcas de su ciudad o región.", por_que:"The Influencer Marketing Factory (EE.UU.) factura 10M$+ conectando marcas con influencers. El ROI del marketing de influencers es de 5.78$ por cada 1$ invertido (Influencer Marketing Hub 2024). Los microinfluencers tienen tasas de engagement del 4-8% vs 1-2% de los macro, y son 6 veces más cost-effective.", como_aplicar:"España tiene 200.000+ creators con 5.000-100.000 seguidores que no tienen representación ni conocen su valor de mercado. Las marcas locales (restaurantes, tiendas, hoteles) quieren usar influencers locales pero no saben cómo contactarlos ni qué pagar. Una agencia que gestiona 50-100 microinfluencers en tu ciudad y los conecta con marcas locales a comisión del 20-30% genera 5.000-15.000€/mes.", riesgos:["Retención de influencers difícil: en cuanto crecen buscan agencias más grandes","Métricas de ROI difíciles de demostrar a marcas locales que no están acostumbradas a este tipo de marketing","Mercado muy fragmentado: cualquier persona con un Excel y un teléfono puede 'montar una agencia'"], pasos:["Crear base de datos de 200 microinfluencers locales en tu ciudad con métricas (seguidores, engagement, nicho)","Lanzar con 5 campañas piloto gratuitas para marcas locales para construir casos de éxito con datos reales","Precio estándar: 500-2.000€ por campaña de 1 semana con 3-5 influencers según alcance","Software de gestión: Grin, CreatorIQ o Excel avanzado para gestión de contratos, briefs y métricas"] },

  { id:73, nombre:"Centros de Día para Personas Mayores Activas", emoji:"👵", sector:"Salud", potencial:"Alta", dificultad:"Moderada", resumen:"Espacios de día para mayores de 65 años con actividades estimulantes, tecnología, cultura, deporte y socialización de calidad.", por_que:"Sunrise Senior Living (EE.UU.) vale 1.500M$. El mercado de senior living alcanzará 85.000M$ en 2030. En EE.UU., el nuevo modelo de centro de día activo (non-medical day program) tiene lista de espera en la mayoría de ciudades. La soledad es la principal causa de deterioro cognitivo en mayores: las actividades de estimulación reducen el riesgo de Alzheimer un 35% (Lancet 2024).", como_aplicar:"España tiene 350.000 plazas en centros de día para mayores pero el 80% son básicos y medicalizados (gerontocultura de 'bingo y telenovelas'). Una propuesta premium de centro de día activo orientado a mayores de 65 años autónomos pero solitarios, con clases de inglés, tecnología, yoga, cocina, salidas culturales y conexión intergeneracional a 500-1.200€/mes tiene diferenciación radical.", riesgos:["Autorización de centro de día de mayores por comunidad autónoma: proceso de 6-18 meses según región","Ratio de personal obligatorio: mínimo 1 cuidador por cada 6-8 usuarios según normativa, encarece la operación","Estigma de 'centro de mayores': el marketing debe huir del lenguaje de 'residencia' y usar 'club social para mayores activos'"], pasos:["Investigar requisitos de autorización de centro de día en tu comunidad autónoma antes de cualquier inversión","Local de 200-350m² en planta baja con accesibilidad total, jardín o terraza si es posible","Programa de actividades diferenciado: English club, smartphone taller, yoga suave, cocina internacional, cine debate","Canal de captación: médicos de familia, trabajadores sociales y grupos de Facebook de hijos adultos cuidadores"] },

  { id:74, nombre:"Alquiler de Ropa de Bebé y Equipamiento Infantil", emoji:"🍼", sector:"Retail", potencial:"Alta", dificultad:"Fácil", resumen:"Suscripción de alquiler de ropa de bebé (0-24 meses) y equipamiento infantil (sillitas, tronas, cunas) por el tiempo que se necesita.", por_que:"Bundlee (UK) tiene 10.000 suscriptores alquilando ropa de bebé. Kidizen (EE.UU.) procesa 1M$ mensuales en ropa infantil de segunda mano. Los bebés crecen tan rápido que la mayoría de ropa se usa 3-6 veces: comprar no tiene ningún sentido económico. El mercado de alquiler de productos de bebé crecerá al 18% anual hasta 2028.", como_aplicar:"España tiene 300.000 nacimientos anuales y los padres gastan de media 3.000€ en el primer año en ropa y equipamiento. El 78% de madres españolas declara que 'la ropa de bebé nueva es un derroche' pero no encuentra alternativas de calidad (encuesta Chicco 2024). Un servicio de alquiler de packs de ropa de bebé por talla (0-3m, 3-6m, 6-9m, etc.) a 29-49€/mes con envío y recogida a domicilio tiene propuesta clarísima.", riesgos:["Higiene y limpieza de ropa de bebé: protocolo de lavado certificado a 60°C con detergente hipoalergénico es obligatorio para la confianza","Inventario inicial significativo: 500-1.000 piezas de ropa de calidad para 20-30 suscriptores iniciales","Tasa de abandono alta cuando el bebé pasa a 2 años y la demanda cae: el negocio vive de la rotación de nuevas suscriptoras"], pasos:["Empezar con 3 packs de ropa por talla (0-3m, 3-6m, 6-12m) con 10 piezas esenciales cada uno","Protocolo de higiene certificado y comunicado transparentemente: el primer miedo de la madre es la higiene","Canal: grupos de Facebook de madres primerizas (los más grandes de España tienen 100.000+ miembros)","Fotografía profesional de los packs: la presentación visual en Instagram determina el 80% de la conversión"] },

  { id:75, nombre:"Agencia de Nómadas Digitales y Relocalización", emoji:"🌐", sector:"Servicios", potencial:"Alta", dificultad:"Fácil", resumen:"Servicio de asesoramiento y gestión logística para profesionales que quieren trabajar en remoto desde España o desde el extranjero.", por_que:"MBO Partners (EE.UU.) reporta 17 millones de nómadas digitales americanos en 2023, crecimiento del 131% en 4 años. España ofrece la 'visa nómada digital' desde 2023. El mercado de servicios de relocalización para nómadas digitales alcanzará 1.300M$ en 2026. El nómada digital gasta de media 2.500-5.000€ en servicios de establecimiento en un nuevo país.", como_aplicar:"España se ha convertido en el destino favorito de nómadas digitales europeos y americanos: Málaga, Valencia y Las Palmas encabezan todos los rankings. Un servicio que gestiona la visa de nómada digital española (documentación, NIE, banco, seguro médico, apartamento) a 1.500-3.000€ por cliente tiene un mercado de 50.000 solicitudes anuales solo en España.", riesgos:["Regulación de asesoría de visas: borderline con servicios de abogados/gestores habilitados","Los requisitos de la visa nómada cambian con frecuencia: necesitas actualización constante","Mercado muy fragmentado con muchos freelancers que ofrecen lo mismo de forma informal"], pasos:["Establecer colaboración con gestoría o abogado especializado en extranjería para la parte legal","Producto estandarizado: 'Pack de aterrizaje en Málaga' (visa + NIE + cuenta bancaria + seguro + piso de 1 mes a 2.490€ todo incluido)","Canal: grupos de Facebook de Digital Nomads in Spain, Reddit r/digitalnomad y TikTok en inglés","Crecer hacia otros destinos cuando el proceso esté estandarizado: Valencia Pack, Canarias Pack"] },

  { id:76, nombre:"Escuelas de Surf y Deportes de Agua por Suscripción", emoji:"🏄", sector:"Fitness & Salud", potencial:"Alta", dificultad:"Moderada", resumen:"Escuelas de surf, kitesurf, windsurf o paddle surf con modelo de membresía mensual que incluye clases ilimitadas para principiantes y progresión.", por_que:"WSL (World Surf League) reporta 35 millones de surfistas en EE.UU. Surf instructor business en EE.UU. genera 50.000-150.000$/año. El modelo de membresía en escuelas de deporte de agua tiene ingresos recurrentes vs el modelo de clases sueltas: el LTV del miembro es 5-8 veces superior.", como_aplicar:"España tiene 6.000km de costa con condiciones para surf y deportes de agua. Tarifa, Fuerteventura, Zarautz y Mundaka son destinos de surf de clase mundial. Una escuela con modelo de membresía de 79-129€/mes con clases 3x/semana, préstamo de material incluido y programa de progresión certificado tiene diferenciación total vs escuelas de clases sueltas a 40€ la hora.", riesgos:["Estacionalidad: en destinos del norte el invierno puede reducir el negocio un 70%","Seguro obligatorio de responsabilidad civil para actividades acuáticas con alto riesgo: 2.000-5.000€/año","Material de surf (tablas, trajes): 500-1.000€ por set completo, con vida útil de 2-3 años de uso intensivo"], pasos:["Calcular el número mínimo de socios para cubrir costes: alquiler de local, seguros, material y instructores","Lanzar con precio fundador: 59€/mes los 6 primeros meses para los primeros 50 socios","Programa de progresión certificado (principiante → intermedio → avanzado) como diferenciador de retención","Crear comunidad: eventos sociales, viajes de surf, torneos internos para que el socio no se vaya aunque no avance tan rápido"] },

  { id:77, nombre:"Plataforma de Economía Circular para Empresas", emoji:"♻️", sector:"Sostenibilidad", potencial:"Alta", dificultad:"Moderada", resumen:"Marketplace B2B que conecta empresas con excedentes de materiales o maquinaria con empresas que los necesitan, evitando el vertedero.", por_que:"Rheaply (EE.UU.) ha gestionado la reutilización de 200M$+ en activos empresariales. eBay Business Supply genera 5.000M$ en activos B2B de segunda mano. En EE.UU., las empresas destruyen o tiran 8.000M$ en maquinaria y materiales aprovechables anuales. La economía circular empresarial es una obligación regulatoria en la UE desde 2025.", como_aplicar:"La Ley de Residuos española de 2022 obliga a las empresas a priorizar la reutilización sobre el reciclaje. Las grandes empresas tienen almacenes llenos de maquinaria, mobiliario de oficina y materiales de producción que no usan pero no saben cómo vender. Un marketplace B2B que gestiona la valorización de estos activos a cambio del 15-25% del valor obtenido tiene propuesta de valor tanto económica como de cumplimiento regulatorio.", riesgos:["Liquidez del marketplace: los compradores no vienen si no hay oferta y los vendedores no listan si no hay compradores","Logística de materiales industriales voluminosos y pesados: coste de transporte puede hacer inviable la transacción","Valoración de activos usados es subjetiva y puede generar disputas entre vendedor y comprador"], pasos:["Empezar con un sector específico: mobiliario de oficina de empresas que se trasladan o cierran (alta disponibilidad)","Acuerdo con empresa de mudanzas corporativas para aprovisionamiento sistemático de oferta","Plataforma simple: Shopify adaptado o Sharetribe (marketplace engine) para reducir coste de desarrollo","Clientes compradores iniciales: startups, pymes en crecimiento, ONGs y organismos públicos que buscan precio bajo"] },

  { id:78, nombre:"Apps de Telemedicina para Colectivos Específicos", emoji:"🩺", sector:"Salud", potencial:"Alta", dificultad:"Moderada", resumen:"Plataforma de consultas médicas online especializada en un colectivo específico: expatriados, deportistas, mujeres embarazadas o pacientes crónicos.", por_que:"Hims & Hers (EE.UU.) fue valorada en 2.000M$ especializándose en salud masculina y femenina. Ovia Health (embarazo) tiene 14 millones de usuarias. La especialización en telemedicina genera ARPU 3-4 veces superior a la telemedicina generalista y tasas de retención del 70% vs 40% de plataformas genéricas.", como_aplicar:"Doctoralia y Top Doctors operan en España como plataformas generalistas con millones de usuarios. Pero una plataforma especializada, por ejemplo, en 'salud de deportistas amateur' (lesiones, nutrición deportiva, cardiología preventiva) con médicos deportivos disponibles en 24h y seguimiento de entrenamientos conectado al wearable tiene diferenciación y precio premium.", riesgos:["Reclutamiento de médicos especialistas en el nicho elegido: escasos y con salarios altos","Regulación sanitaria específica según el tipo de paciente (embarazadas, menores, pacientes con patología crónica)","Competencia de plataformas generalistas bien financiadas que añaden especialidades progresivamente"], pasos:["Elegir nicho con combinación de alta demanda + problema mal resuelto hoy: deportistas es el mejor point of entry","Reclutar 10 médicos especialistas del deporte y nutricionistas deportivos para el MVP","Integración con wearables (Garmin, Polar, Apple Watch) para contextualizar la consulta con datos reales del deportista","Canal: clubes deportivos, federaciones regionales de atletismo/ciclismo/triatlón como distribuidores de la plataforma"] },

  { id:79, nombre:"Servicios de Detox Digital y Retiros de Desconexión", emoji:"🧘", sector:"Entretenimiento", potencial:"Media", dificultad:"Fácil", resumen:"Retiros de 2-5 días en entorno rural o de montaña con prohibición total de smartphones, actividades de mindfulness y reconexión con la naturaleza.", por_que:"Camp Grounded (EE.UU.) agotó sus retiros en 48h con precio de 500-900$. Digital Detox (organización americana) tiene 20.000+ participantes anuales. El 74% de americanos declara sentirse 'adicto al smartphone' (Gallup 2024) y el 43% pagaría por ayuda para desconectar. El bienestar digital es la tendencia de mayor crecimiento en wellness.", como_aplicar:"España tiene entornos rurales y de montaña excepcionales para este tipo de retiros. El profesional urbano de 30-45 años que pasa 10+ horas diarias ante pantallas y siente ansiedad por el smartphone es el target perfecto. Un retiro de 3 días en Gredos, Pirineos o Sierra Nevada con yoga, senderismo, meditación, lectura y cero móviles a 350-600€ tiene lista de espera inmediata.", riesgos:["La propuesta de 'sin móvil' puede percibirse como extrema: comunicar el beneficio sin asustar es clave","Logística de alojamiento rural con capacidad de 15-30 personas con toda la infraestructura necesaria","Estacionalidad: primavera y otoño son temporadas ideales; verano e invierno tienen menor demanda para este formato"], pasos:["Empezar alquilando una casa rural completa (10-20 camas) para los primeros retiros: sin inversión en propiedad","Programa de 3 días estructurado: actividades mañana, tarde libre en naturaleza, taller nocturno de reflexión","Precio de lanzamiento: 299€ todo incluido para los primeros 20 participantes con reseña comprometida","Canal: grupos de meditación, yoga y bienestar en Facebook; comunidades de mindfulness en Instagram"] },

  { id:80, nombre:"Asesoría Fiscal para Creadores de Contenido", emoji:"📹", sector:"Tech", potencial:"Alta", dificultad:"Fácil", resumen:"Gestoría especializada en YouTubers, streamers, influencers y creadores de contenido: facturación de plataformas, IVA internacional, declaración de criptomonedas.", por_que:"Creator economy alcanzará 480.000M$ en 2027 (Goldman Sachs). Hay 2 millones de creadores de contenido con ingresos en EE.UU. El 73% de creadores declara que 'la fiscalidad es su mayor dolor de cabeza' (Creator Economy Report 2024). Las gestorías tradicionales no entienden las especificidades (ingresos en dólares de AdSense, suscripciones de Twitch, donaciones en cripto, colaboraciones con marcas).", como_aplicar:"España tiene 150.000+ creadores de contenido con ingresos (Statista 2024) y prácticamente ninguna gestoría especializada en su casuística. Los ingresos de YouTube (Google Irlanda), Twitch (Amazon Luxemburgo), TikTok Creator Fund y marcas internacionales tienen tratamiento fiscal específico diferente al del autónomo tradicional. Una gestoría a 79-149€/mes especializada en este colectivo tiene captación orgánica muy fácil por YouTube e Instagram.", riesgos:["Requiere actualización constante: la fiscalidad de plataformas digitales y cripto cambia cada 6-12 meses","Responsabilidad legal alta: un error en la declaración puede generar sanciones graves al cliente","Competencia de gestorías generalistas que añaden este servicio progresivamente"], pasos:["Crear contenido educativo (YouTube, TikTok) sobre fiscalidad de creadores antes de lanzar: captación orgánica gratuita","Paquete estándar: alta de autónomo + gestión trimestral IVA/IRPF + asesoramiento de plataformas a 99€/mes","Especialización adicional: criptomonedas y NFTs como servicio premium a 149€/mes","Comunidad de Discord de creadores de contenido español como canal de distribución orgánica"] },

  { id:81, nombre:"Talleres de Cerámica y Artesanía Moderna", emoji:"🏺", sector:"Entretenimiento", potencial:"Alta", dificultad:"Fácil", resumen:"Estudios de cerámica, macramé, encuadernación o vidrieras con clases para adultos en formato social y experiencia de tarde.", por_que:"Pottery classes son el 'nuevo yoga' en EE.UU.: Pottery Barn ofrece clases en sus tiendas generando 30M$+ adicionales. Goldmark Art (UK) factura 10M$+ en talleres de bellas artes. La economía del 'hacer con las manos' (maker economy) creció un 300% desde 2019. El adulto de 25-45 años busca actividades sin pantallas que generen algo tangible.", como_aplicar:"En las ciudades españolas medianas prácticamente no existen estudios de cerámica para adultos con enfoque social y moderno. Los que hay son anticuados y con precios bajos. Un estudio de cerámica con brand identity cuidada (Instagram-worthy), formato social (2-3 personas por torno, copa de vino incluida), música lo-fi y clases de 2,5h a 35-55€/persona tiene lista de espera en 3 semanas desde la apertura.", riesgos:["Inversión en hornos de cerámica eléctricos: 3.000-8.000€ cada uno, necesitas mínimo 2","Gestión de arcilla, esmaltes y materiales: coste continuo y logística de proveedores especializados","Formato experiencial tiene techo de capacidad bajo: máximo 8-12 personas por clase limita el potencial de escala"], pasos:["Local de 60-100m² con entrada de luz natural: el espacio es un argumento de venta en Instagram","Inversión inicial: 2 hornos + 6-8 tornos eléctricos + mesas de trabajo + arcilla y esmaltes: 20.000-35.000€","Lanzar con 'clase de inicio' de 2,5h a 35€ para validar demanda antes de ofrecer cursos de 10 semanas","Instagram como canal principal: publicar proceso, resultado y la expresión de alegría del alumno convierte perfectamente"] },

  { id:82, nombre:"Gestión de Herencias y Legados Digitales", emoji:"📜", sector:"Servicios", potencial:"Alta", dificultad:"Moderada", resumen:"Servicio de organización, valoración y gestión integral de herencias: inventario de bienes físicos y digitales, coordinación con notaría e intermediación entre herederos.", por_que:"Trust & Will (EE.UU.) fue valorada en 300M$ con 500.000 usuarios. Settle (herencias online) procesó 1.000M$ en herencias en 2023. El mercado de gestión de herencias en EE.UU. alcanzará 1.000M$ en 2026. El baby boom español creará una avalancha de herencias en los próximos 15 años: se estima que 800.000M€ cambiarán de manos en España entre 2020 y 2040.", como_aplicar:"España procesa 350.000 herencias anuales (Consejo General del Notariado 2024) con un proceso kafkiano que puede durar 12-24 meses y costar 10.000-30.000€ en gestorías y abogados. El 67% de las herencias tienen conflictos entre herederos. Un servicio de gestión de herencias que ofrece proceso completo a precio fijo (no a %, que es lo que encarece el coste actual) con plataforma digital para compartir documentos entre herederos tiene propuesta muy atractiva.", riesgos:["Regulación de intermediación en herencias: se solapa con funciones de gestores, abogados y notarios (consultar colegio de abogados)","Gestión emocional difícil: los clientes están en duelo y con frecuencia tienen conflictos familiares serios","Conocimiento técnico específico: fiscalidad de herencias, impuesto de sucesiones (varía por comunidad autónoma), derecho civil sucesorio"], pasos:["Equipo cofundador con gestor administrativo + abogado especializado en derecho sucesorio","Producto digital: inventario online de bienes con estimación de valor + coordinación de documentación entre herederos","Precio fijo: 1.500€ (proceso básico sin inmuebles) o 3.500€ (proceso completo con inmuebles y activos financieros)","Canal: funerarias como prescriptores (tienen acceso a familias en el momento exacto de necesidad)"] },

  { id:83, nombre:"Tutorías de Idiomas con Nativos Verificados", emoji:"🌍", sector:"Educación", potencial:"Alta", dificultad:"Fácil", resumen:"Plataforma de clases particulares de idiomas con nativos verificados, schedule flexible y sistema de matching por objetivos y nivel.", por_que:"iTalki tiene 5 millones de usuarios y fue adquirida por Preply (que vale 300M$). Cambly tiene 50.000 tutores nativos y 1 millón de estudiantes. El mercado de tutorías de idiomas online alcanzará 22.000M$ en 2027. La demanda de inglés conversacional con nativos ha crecido un 45% desde el COVID.", como_aplicar:"España tiene el nivel de inglés más bajo de la Europa occidental (EF EPI 2024) y el desempleo juvenil más alto: la barrera idiomática es el principal freno laboral. Una plataforma que conecta nativos angloparlantes viviendo en España (abundantes, buscan ingresos extra) con españoles que quieren mejorar su inglés conversacional a 12-18€/hora tiene una propuesta de valor simple y captación fácil para ambos lados.", riesgos:["Competencia directa de iTalki, Preply y Cambly con millones en marketing y red global de tutores","Confianza en la calidad del tutor: la verificación es cara pero imprescindible para diferenciarse","Margen comprimido: los tutores quieren el 70-80% del precio, dejando poco para la plataforma"], pasos:["Diferenciador clave: solo nativos viviendo en España (zonas horarias compatibles, cultura española compartida)","Matching por objetivos específicos: inglés de negocios, preparación IELTS, inglés para médicos o abogados","Captación de tutores: grupos de Facebook de 'English speakers in Spain' en Madrid, Barcelona, Sevilla y Málaga","Primera versión: Calendly + Stripe + Zoom sin desarrollo propio para validar demanda antes de invertir en plataforma"] },

  { id:84, nombre:"Seguros de Hogar por IA y Telemática", emoji:"🏠", sector:"Finanzas", potencial:"Media", dificultad:"Difícil", resumen:"Seguros del hogar con precio dinámico basado en sensores IoT que miden el riesgo real: presencia, temperatura, humo, agua y seguridad.", por_que:"Hippo Insurance (EE.UU.) fue valorada en 5.000M$ en su IPO con seguros de hogar inteligente. Lemonade tiene 1,8 millones de asegurados y procesa siniestros con IA en 3 segundos. El mercado de insurtech alcanzará 10.000M$ en 2025. El 70% de siniestros del hogar son detectables previamente con sensores básicos.", como_aplicar:"El mercado de seguros del hogar en España es de 3.000M€ anuales pero completamente no diferenciado: todos ofrecen lo mismo a precio similar. Una aseguradora que reduce el precio un 20-40% a cambio de instalar 3 sensores IoT (humo, agua y presencia) que permiten detección preventiva de siniestros tiene propuesta diferenciada y margen de siniestralidad real un 30% inferior.", riesgos:["Regulación de seguros en España: Dirección General de Seguros requiere autorización y capital mínimo de 3.3M€","Operación como agente de seguros vinculado o mediador requiere registro en la DGSFP","Instalación de sensores en hogares ajenos: fricción operativa alta y coste de hardware de 50-150€ por hogar"], pasos:["Modelo de entrada: mediador de seguros (no aseguradora) que vende seguros de hogar de terceros con diferenciación tecnológica","Acuerdo con aseguradora establecida para ser su 'canal digital con sensores' sin necesitar capital de aseguradora","Sensor IoT: kit de 3 sensores Fibaro o similar a 60-90€ que se instala en 20 minutos sin obra","Descuento del 25% en la prima a cambio de instalar los sensores y compartir los datos con la aseguradora"] },

  { id:85, nombre:"Centros de Trabajo en Remoto en Destinos Rurales (Coliving)", emoji:"🏘️", sector:"Inmobiliario", potencial:"Alta", dificultad:"Moderada", resumen:"Espacios de coliving y coworking en pueblos españoles despoblados con alta calidad de vida, fibra óptica y comunidad de nómadas digitales.", por_que:"Remote Year tiene 2.000+ alumni y fue vendida por 50M$. Selina opera 150+ propiedades para nómadas. El programa 'Trabajo Desde Canarias' atrajo 8.000 nómadas en 6 meses. España tiene 3.500 municipios en riesgo de despoblación con casas a 30.000-80.000€ que con 50.000€ de reforma se convierten en coliving premium.", como_aplicar:"El Gobierno español subvenciona proyectos de repoblación rural con hasta 150.000€ (Estrategia Nacional frente al Reto Demográfico). El teletrabajador europeo paga 800-1.500€/mes por un espacio de coliving en ciudad vs 400-700€ en un pueblo con naturaleza, tranquilidad y fibra óptica. Molinos (Teruel), Porreras (Mallorca) o Cuacos de Yuste (Cáceres) tienen potencial turístico y de calidad de vida únicos.", riesgos:["Inversión en reforma de casas rurales: 50.000-150.000€ por propiedad para alcanzar estándares de nómadas digitales","Conectividad: la fibra no llega a todos los municipios rurales (aunque mejora rápidamente)","Captación de nómadas digitales es internacional: marketing en inglés, alemán y francés necesario"], pasos:["Identificar municipio con ayuntamiento colaborativo, fibra óptica o 5G, y acceso a ciudad grande en <90 minutos","Negociar compra o alquiler de 3-5 casas contiguas para crear un mini-village de nómadas","Subvenciones: Plan de Recuperación, programa LEADER de la UE y estrategia nacional de despoblación","Lanzar en plataformas como Nomad List, Remote OK y grupos de Facebook de nómadas digitales"] },

  { id:86, nombre:"Servicios de Personal Shopper Online", emoji:"👜", sector:"Retail", potencial:"Alta", dificultad:"Fácil", resumen:"Servicio de selección personalizada de ropa, decoración o regalos por suscripción o proyecto: el cliente recibe propuestas curadas sin ir de compras.", por_que:"Stitch Fix (EE.UU.) fue valorada en 4.200M$ con 3.5 millones de clientes activos. Trunk Club (adquirida por Nordstrom por 350M$). El mercado de personal shopping alcanzará 2.700M$ en 2026. El 67% de hombres de 25-45 años odia ir de compras; el 48% de mujeres declara que 'no sabe qué ponerse' a pesar de tener ropa.", como_aplicar:"En España el personal shopping físico existe para clientes de alto poder adquisitivo (200-500€/sesión). Un servicio online a 29-79€/mes donde un estilista analiza tu estilo, presupuesto y guardarropa y te manda selecciones de marcas como Zara, Mango, H&M o marcas independientes tiene propuesta asequible y escalable.", riesgos:["Personalización real requiere estilistas humanos: escala con dificultad y los costes crecen con los clientes","Tasa de abandono alta si las selecciones no gustan: las primeras 3 cajas determinan la retención del cliente","Competencia de los propios algoritmos de recomendación de las tiendas online"], pasos:["Crear cuestionario de estilo muy detallado: 15-20 preguntas con referencias visuales (Pinterest, ejemplos de outfits)","Lanzar con servicio de 'selección mensual de 5 prendas' a 39€/mes: el estilista selecciona, el cliente compra solo lo que quiere","Canal: Instagram con contenido de 'antes y después del armario' y LinkedIn para servicio de imagen profesional","Empezar con mujeres de 30-45 años ejecutivas que quieren 'vestir bien sin pensar'"] },

  { id:87, nombre:"Clínicas de Fertilidad de Segunda Opinión", emoji:"👶", sector:"Salud", potencial:"Alta", dificultad:"Difícil", resumen:"Servicio de segunda opinión médica especializada en fertilidad y reproducción asistida para parejas que ya han recibido un diagnóstico o tratamiento.", por_que:"CCRM Fertility (EE.UU.) genera 100M$+ con clínicas de fertilidad premium. La industria de fertilidad en EE.UU. alcanzará 10.000M$ en 2027. El 65% de parejas con problemas de fertilidad busca segunda opinión antes de iniciar un tratamiento de 10.000-30.000€. La demanda de fertilidad crece por el retraso de la maternidad: el 35% de primeras madres españolas tiene >35 años.", como_aplicar:"España tiene el mayor número de clínicas de reproducción asistida de Europa (300+) pero la segunda opinión especializada es casi inexistente: las clínicas tienen conflicto de interés obvio. Un servicio de 300-600€ por segunda opinión médica independiente con revisión del historial, análisis crítico del tratamiento propuesto y recomendación alternativa tiene valor claro para una pareja a punto de gastar 15.000€.", riesgos:["Requiere médico ginecólogo especialista en reproducción asistida: escaso y costoso","Riesgo de conflictos con clínicas cuyo tratamiento cuestionamos: posible presión del sector","Alta responsabilidad: el cliente tomará decisiones médicas importantes basándose en tu opinión"], pasos:["Médico cofundador especialista en reproducción asistida como requisito absoluto para arrancar","Servicio inicial 100% remoto: revisión de historial médico + videoconsulta de 60 minutos a 350€","Canal de captación: foros de fertilidad en internet (son comunidades muy activas y muy grandes)","Modelo complementario: charlas en grupos de fertilidad y colaboración con psicólogos especializados en pérdidas gestacionales"] },

  { id:88, nombre:"Plataforma de Patrimonio Fotográfico Familiar", emoji:"📷", sector:"Tech", potencial:"Media", dificultad:"Fácil", resumen:"Servicio de digitalización, organización con IA y preservación de fotografías y vídeos familiares analógicos (carretes, VHS, Super 8).", por_que:"Legacybox (EE.UU.) ha digitalizado 1 millón de cajas de recuerdos familiares a 150-800$ cada una. ScanMyPhotos procesa 5 millones de fotos mensuales. El mercado de digitalización de memorias alcanzará 1.900M$ en 2026. Cada año se pierden irreversiblemente millones de fotografías por deterioro de películas analógicas.", como_aplicar:"España tiene 40 millones de hogares con un promedio de 200-500 fotos analógicas y 5-15 películas de VHS o Super 8 sin digitalizar. El 80% declara querer digitalizarlas 'algún día' pero nunca lo hace (encuesta Fnac 2024). Un servicio de recogida a domicilio + digitalización profesional + entrega en disco duro o nube a 99-299€ tiene conversión muy alta entre familias de 40-60 años.", riesgos:["Responsabilidad extrema: si se pierden o dañan los originales, el impacto emocional es devastador","Equipamiento de digitalización profesional de fotografías y VHS: 3.000-8.000€ de inversión inicial","Proceso intensivo en mano de obra: cada carrete requiere 30-60 minutos de trabajo manual de escaneo"], pasos:["Empezar con digitalización de fotos impresas y carretes (más simple que VHS o Super 8)","Packaging de recogida muy cuidado: caja acolchada con instrucciones claras transmite confianza desde el primer contacto","Proceso de tracking online: el cliente puede ver en qué fase está su pedido en tiempo real (reduce ansiedad)","Canal: grupos de Facebook de familias y abuelos + campañas de Navidad y Día de la Madre donde el regalo emocional convierte muy bien"] },

  { id:89, nombre:"Franquicias de Estudio de Grabación por Horas", emoji:"🎵", sector:"Entretenimiento", potencial:"Media", dificultad:"Moderada", resumen:"Estudios de grabación profesionales accesibles para músicos amateurs y podcasters por horas, con equipo de alta calidad incluido.", por_que:"Pirate Studios (UK) tiene 50+ estudios de grabación por horas en 10 países y fue valorada en 200M$. El mercado de creación de contenido musical amateur ha explotado con TikTok, Spotify y YouTube: 100 millones de músicos amateurs en EE.UU. necesitan acceso a equipamiento profesional que no pueden permitirse comprar.", como_aplicar:"España tiene 500.000+ músicos amateurs que graban con equipos caseros de baja calidad. Los estudios de grabación profesionales cobran 50-150€/hora y están orientados a músicos profesionales. Un estudio con equipamiento profesional (micrófono Neumann, preamplificador API, Pro Tools) accesible por 20-35€/hora con reserva por app 24h en local de 60-80m² en ciudad universitaria tiene mercado claro.", riesgos:["Inversión en equipamiento de audio profesional: 20.000-50.000€ para sonido de calidad real","Mantenimiento de equipamiento delicado y uso intensivo por amateurs que no saben tratar el equipo","Ticketazo medio bajo: 2 horas de grabación = 50-70€; necesitas alta ocupación para amortizar inversión"], pasos:["Sistema de reservas automático por app: sin recepcionista ni horarios limitados","Equipamiento esencial: Yamaha C5 Steinway (piano digital), Neumann TLM 103, Apollo Twin interface, Pro Tools","Sala de control separada de la cabina para que el músico no necesite ingeniería de sonido propia","Oferta adicional: servicio de mezcla y masterización por ingeniero freelance como upsell de mayor margen"] },

  { id:90, nombre:"Plataforma de Retos de Hábitos en Comunidad", emoji:"🏆", sector:"Fitness & Salud", potencial:"Alta", dificultad:"Fácil", resumen:"App de retos de 30-90 días (correr, meditar, ayuno intermitente, lectura) en grupos de accountability con amigos o extraños, con premios reales.", por_que:"Beachbody (EE.UU.) genera 700M$ anuales con programas de 60-90 días en comunidad. Habitica tiene 4 millones de usuarios gamificando los hábitos. GoalMap fue adquirida por BNP Paribas. El 72% de personas que participan en retos en comunidad completan sus objetivos vs 35% de las que lo hacen solas (Journal of Applied Psychology 2024).", como_aplicar:"En España las apps de hábitos son principalmente americanas y sin comunidad local. Una plataforma en español donde grupos de 5-10 personas hacen un reto de 30 días juntos con check-ins diarios, accountability partner asignado y premio al grupo que completa (bono de experiencias, descuentos, donación a ONG elegida) tiene propuesta diferenciada por la comunidad real.", riesgos:["Retención a largo plazo: después de completar un reto, ¿por qué volver? Necesitas diseño de siguiente reto inmediato","Monetización delicada: la comunidad gratis es el motor de crecimiento pero no paga las facturas","Competencia de apps grandes (Strava, MyFitnessPal, Headspace) que añaden funciones de comunidad progresivamente"], pasos:["MVP: grupo de WhatsApp con check-in diario automatizado por bot para validar si el modelo de accountability funciona","Monetización inicial: retos premium de 90 días a 29€ con acceso a coach humano una vez por semana","Partnerships con marcas de deportes, nutrición y bienestar para los premios del reto (coste cero o reverso)","Canal de captación: influencers de fitness y bienestar como embajadores del primer reto"] },

  { id:91, nombre:"Talleres de Construcción de Muebles", emoji:"🪵", sector:"Entretenimiento", potencial:"Media", dificultad:"Fácil", resumen:"Espacio con herramientas profesionales y guía experta para que adultos construyan sus propios muebles o hagan reparaciones del hogar.", por_que:"TechShop (EE.UU.) fue valorada en 50M$ con espacios de maker. Home Depot organiza talleres en sus tiendas generando 30M$ adicionales anuales. El 58% de millennials americanos quiere aprender carpintería o bricolaje pero no tiene herramientas ni espacio (Popular Mechanics 2024). El movimiento DIY (Do It Yourself) es la tendencia más grande de YouTube con 5.000M+ de visualizaciones.", como_aplicar:"España tiene una cultura de bricolaje decreciente (IKEA ha sustituido la carpintería artesanal) pero una nostalgia creciente por el trabajo manual. Un taller con sierra de cinta, torno de madera, herramientas de mano y un instructor que guía a grupos de 4-6 personas a construir una pieza concreta (estantería flotante, mesa de café, cabecero) en una sesión de 4h a 55-85€/persona tiene mercado en ciudades grandes.", riesgos:["Seguridad: el uso de herramientas eléctricas por amateurs requiere protocolos estrictos y seguro específico","Espacio industrial de 200-400m² con ventilación y aspiración de polvo es caro en zonas céntricas","Aprovisionamiento de madera: el precio de la madera noble se ha disparado un 40% desde 2021"], pasos:["Local industrial de 200-400m² en polígono artesanal: alquiler más asequible que en zona comercial","Inversión en herramientas: sierra de cinta, torno de madera, lijadora orbital, sierra de mesa: 15.000-25.000€","Formato de 'taller de proyecto cerrado': en 4h construyes exactamente esto, con estas medidas y te lo llevas a casa","Canal: Eventbrite para primeros talleres + Instagram con proceso y resultado final"] },

  { id:92, nombre:"Servicios de Relevo Gerencial para PYMEs", emoji:"👔", sector:"Servicios", potencial:"Alta", dificultad:"Moderada", resumen:"Directivos interinos que gestionan una PYME durante una transición: enfermedad del fundador, venta de la empresa, expansión internacional o crisis.", por_que:"InterimCFO (EE.UU.) genera 200M$+ en facturación. El mercado de directivos interinos alcanzará 15.000M$ en EE.UU. en 2027. El 40% de las PYMEs americanas experimenta una crisis de liderazgo en los primeros 10 años que podría evitarse con un directivo interino cualificado.", como_aplicar:"Spain tiene 3 millones de PYMEs y el 65% tiene un único directivo clave (el fundador) sin plan de sucesión. Cuando el fundador enferma, viaja o se jubila, la empresa entra en crisis. Un servicio de directivo interino (CEO, CFO, COO según necesidad) a 3.000-8.000€/mes con contrato de 3-12 meses es infinitamente más económico que contratar a un directivo fijo o que perder la empresa.", riesgos:["Requiere directivos de primer nivel con experiencia real como CEO/CFO: pool de talento limitado y caro","Confianza necesaria: el empresario debe ceder el control a una persona externa, resistencia cultural alta","Cada asignación es diferente: no hay economía de escala operativa, cada caso requiere curva de aprendizaje"], pasos:["Crear red de 20-30 directivos seniors semi-retirados o en transición como pool de talento propio","Metodología estándar de onboarding de 2 semanas para cualquier tipo de PYME","Precio claro: 4.500€/mes para 3 días/semana de trabajo dedicado durante mínimo 3 meses","Canal: despachos de abogados mercantilistas, asesores fiscales y bancos como prescriptores en situaciones de crisis"] },

  { id:93, nombre:"Plataforma de Recambios Europeos para Coches Clásicos", emoji:"🚗", sector:"Retail", potencial:"Media", dificultad:"Moderada", resumen:"Marketplace especializado en recambios, piezas originales y restauración de vehículos clásicos con verificación de autenticidad.", por_que:"Hemmings Motor News (EE.UU.) genera 30M$+ en clasificados de coches clásicos. ClassicCars.com fue valorada en 50M$. El mercado de vehículos clásicos es el activo alternativo de mayor crecimiento: +15% anual vs -3% de arte y +8% del vino (Knight Frank Wealth Report 2024). Cada Volkswagen Golf MK1 o Seat 124 requiere piezas originales cada vez más escasas.", como_aplicar:"España tiene el mayor parque de coches clásicos europeos (500.000+ vehículos con más de 30 años, RACE 2024) y una comunidad de propietarios apasionados con alto poder adquisitivo dispuestos a pagar prime por piezas originales. Un marketplace con verificación de autenticidad de piezas, importación desde Europa del Este (donde quedan muchos recambios) y servicio de búsqueda activa de piezas específicas tiene nicho claro.", riesgos:["Mercado muy fragmentado y opaco: los mejores proveedores son pequeños talleres con décadas de relaciones personales","Autenticidad de piezas difícil de verificar sin expertise técnico del modelo específico","Internacionalización necesaria: los recambios están en Alemania, Polonia y UK, lo que complica la logística"], pasos:["Empezar con 2-3 modelos muy populares en España: Seat 600, Citroen 2CV, Volkswagen Golf MK1","Red de proveedores en España + Alemania + Polonia + UK para los modelos elegidos","Sistema de verificación básico: fotografías desde múltiples ángulos + garantía de devolución si la pieza no es auténtica","Comunidad: grupos de Facebook y foros específicos de cada modelo como canal de captación y distribución"] },

  { id:94, nombre:"Coaching de Imagen y Marca Personal para Directivos", emoji:"🎯", sector:"Servicios", potencial:"Alta", dificultad:"Fácil", resumen:"Servicio de desarrollo de marca personal online y offline para ejecutivos, empresarios y profesionales de alto nivel: LinkedIn, presencia pública, comunicación.", por_que:"Ryan Hawk (Leadership coach en EE.UU.) genera 500.000$/año. Impact Theory fue valorada en 50M$ generando content coaching premium. El mercado de executive coaching alcanzará 20.000M$ en 2025. El directivo que trabaja su marca personal crece un 78% más rápido en su carrera y accede a un 3x más de oportunidades (LinkedIn Economic Graph 2024).", como_aplicar:"España tiene 2 millones de directivos y profesionales de alto nivel que no tienen marca personal diferenciada online. El 90% de los ejecutivos españoles no tiene estrategia de LinkedIn, no da conferencias y no publica contenido. Un servicio de 500-2.000€/mes que define la marca personal, crea y gestiona el LinkedIn, prepara el discurso de presentación y entrena para hablar en público tiene mercado premium con bajo coste de adquisición.", riesgos:["El servicio es altamente personalizado: no escala más allá de 10-15 clientes por coach","Resultados tangibles difíciles de medir en el corto plazo: el cliente puede frustrarse","Mercado asociado a la percepción de 'frivolidad' entre directivos conservadores que no ven el ROI"], pasos:["Construir tu propia marca personal primero: si tu LinkedIn no tiene 5.000+ seguidores y contenido regular, no tienes credibilidad","Ofrecer sesión de diagnóstico gratuita de 45 min (análisis de marca personal actual) como puerta de entrada","Paquete inicial: 3 meses de sesiones semanales + gestión de LinkedIn + 1 conferencia preparada = 1.500€/mes","Canal: LinkedIn como plataforma natural de captación para este servicio específico (practica lo que predicas)"] },

  { id:95, nombre:"Mercados de Productores Locales en Pop-up", emoji:"🥕", sector:"Food & Drink", potencial:"Alta", dificultad:"Fácil", resumen:"Mercados semanales organizados en espacios urbanos que conectan a productores locales directamente con consumidores, sin intermediarios.", por_que:"Union Square Greenmarket (NYC) genera 35M$ anuales. Smorgasburg (Brooklyn) genera 8M$ mensuales. El movimiento 'farm to table' en EE.UU. mueve 20.000M$ anuales. Los productores ganan 3-4 veces más vendiendo directo vs a través de distribuidores, y el consumidor paga menos que en el supermercado ecológico.", como_aplicar:"España tiene una producción agrícola y ganadera excepcional pero los productores locales apenas ganan dinero porque cobran precio de commodity. Un mercado semanal que carga al productor 50-150€ por stand + 5-10% de las ventas y al consumidor les acerca producto fresco a precio justo puede generar 3.000-8.000€/semana de ingresos para el organizador en ciudades medianas.", riesgos:["Permisos municipales para mercados en espacios públicos: proceso de 3-6 meses en muchos ayuntamientos","Lluvia y mal tiempo reducen la asistencia un 60-80%: necesitas carpa o espacio cubierto","Logística de comunicación con 20-30 productores cada semana: coordinación costosa en tiempo"], pasos:["Empezar con el mercado de productores dentro de una propiedad privada (centro comercial, parking, local) para evitar trámites municipales","Captación de productores: asociaciones agrarias, cooperativas y productores en redes sociales","Marketing: Instagram con contenido de los productores y sus historias (convierte perfectamente)","Modelo financiero: 80€/stand semanal para 25 stands = 2.000€ de ingresos + % de ventas + patrocinio de marca"] },

  { id:96, nombre:"Autoescuelas Digitales para el Carnet de Conducir", emoji:"🚗", sector:"Educación", potencial:"Alta", dificultad:"Moderada", resumen:"Autoescuela con clases teóricas 100% online, tests adaptativos por IA y clases prácticas on-demand con instructor a domicilio.", por_que:"Zutobi (Suecia) tiene 2 millones de usuarios y fue valorada en 100M$. DriveCoach (EE.UU.) ofrece clases prácticas con instructor a demanda. El modelo online tiene un coste un 40% inferior para el alumno y una tasa de aprobado del examen teórico del 85% vs 62% del modelo presencial (datos DGT-equivalent UK 2024).", como_aplicar:"España tiene 700.000 alumnos que inician el carnet de conducir cada año. El 68% falla el examen teórico a la primera. La app de teoría más usada (Autoescuela Vial) tiene 2 millones de descargas pero ninguna autoescuela ha integrado el ciclo completo: teoría online + prácticas a domicilio + gestión de fecha de examen. Precio actual de carnet: 900-1.500€. Una autoescuela digital podría ofrecer 700-900€ con mejor experiencia.", riesgos:["Regulación de autoescuelas en España (Real Decreto 1295/2003): se requiere Director de Formación titulado y autorización provincial","Las prácticas de conducción requieren instructores con permiso de profesor: coste laboral y logística complejos","Tasa de aprobado del examen práctico (50%) genera frustración que el cliente atribuye a la autoescuela aunque sea de la DGT"], pasos:["Explorar modelo de agencia autorizada: alianza con autoescuela tradicional que da la autorización, tú pones la tecnología","App de teoría con IA adaptativa: el alumno hace test y la IA identifica sus puntos débiles para reforzarlos","Sistema de reservas de clases prácticas con instructor freelance: app tipo Uber pero para instructores de autoescuela","Diferenciador: primera clase gratis + garantía de aprobado o descuento en clases adicionales"] },

  { id:97, nombre:"Gestión de Redes para Profesionales de Salud", emoji:"🩺", sector:"Tech", potencial:"Alta", dificultad:"Fácil", resumen:"Agencia de marketing digital especializada exclusivamente en médicos, fisioterapeutas, psicólogos y otros profesionales de la salud.", por_que:"Healthcare marketing en EE.UU. es un mercado de 33.000M$. El médico o fisioterapeuta independiente necesita marketing pero no tiene tiempo, conocimiento ni confianza en las agencias generalistas que no entienden la normativa sanitaria ni el lenguaje médico. Una agencia especializada en salud cobra un 30-40% más que una agencia genérica.", como_aplicar:"España tiene 200.000+ profesionales de salud con consulta privada o clínica propia. El 80% tiene redes sociales mal gestionadas o inexistentes. La diferencia es que el contenido sanitario tiene restricciones legales (Ley General de Publicidad, restricciones del Colegio de Médicos): una agencia que entiende estas restricciones desde el primer día tiene una ventaja competitiva que una agencia generalista no puede replicar fácilmente.", riesgos:["Restricciones publicitarias sanitarias limitan el tipo de contenido que se puede crear (no testimoniales, no promesas de cura)","Ciclo de venta largo: el profesional sanitario es conservador y tarda en delegar su imagen pública","Difícil demostrar ROI en seguidores vs ROI en nuevos pacientes (la métrica que realmente le importa)"], pasos:["Especializarse aún más: solo fisioterapeutas, o solo psicólogos, o solo clínicas de estética médica","Crear contenido educativo en LinkedIn e Instagram sobre 'cómo captar pacientes con marketing ético' antes de vender","Paquete estándar: gestión de Instagram + Google My Business + 8 posts/mes a 499€/mes","Primer canal: congresos y asociaciones de colegios profesionales sanitarios donde hay acceso masivo al target"] },

  { id:98, nombre:"Alquiler de Espacios de Almacenamiento Inteligente", emoji:"📦", sector:"Servicios", potencial:"Alta", dificultad:"Moderada", resumen:"Trasteros de autoalmacenamiento con acceso 24h, control por app, cámaras y trasteros de diferentes tamaños desde 1m².", por_que:"Public Storage (EE.UU.) vale 49.000M$ en bolsa. Extra Space Storage genera 1.700M$ anuales. El mercado de self-storage alcanzará 70.000M$ en 2027 globalmente. El self-storage tiene los márgenes EBITDA más altos del sector inmobiliario: 60-70% vs 40% de oficinas y 30% de retail.", como_aplicar:"España tiene 10 veces menos metros cuadrados de self-storage per cápita que EE.UU. o UK (FEDESSA 2024). Shurgard (belga) opera en España pero solo en grandes ciudades. Los españoles que se cambian de piso, tienen negocios pequeños o hacen reformas necesitan almacenamiento temporal: el mercado está completamente desatendido en ciudades medianas.", riesgos:["Inversión en habilitación del espacio: seguridad, control de acceso, climatización según el tipo de contenido almacenado","El negocio requiere localización específica: accesible en coche, con aparcamiento, en periferia urbana","Capital inicial significativo: un centro de self-storage de 2.000m² con 200 módulos requiere 300.000-500.000€"], pasos:["Empezar con espacio alquilado de 500-1.000m² en polígono industrial (2-4€/m²/mes): investiga antes de comprar","Módulos de diferentes tamaños: 1m², 3m², 5m², 10m² y 20m² para diferentes perfiles de cliente","Control de acceso por app (Nuki, Dormakaba): el cliente entra con su smartphone sin necesitar personal","Precio de mercado: 15-35€/m²/mes según localización y tamaño del módulo"] },

  { id:99, nombre:"Servicios de Mudanza Internacional para Jubilados", emoji:"✈️", sector:"Servicios", potencial:"Alta", dificultad:"Moderada", resumen:"Agencia especializada en gestionar la mudanza y el asentamiento de jubilados europeos que se trasladan a vivir a España.", por_que:"Spain has become the #1 retirement destination for northern Europeans: 800,000 German, British, French and Dutch retirees live in Spain (INE 2024). EE.UU. tiene un mercado de international relocation para jubilados de 2.000M$. El jubilado europeo que se va a España gasta de media 8.000-20.000€ en servicios de establecimiento y traslado.", como_aplicar:"Una agencia que gestiona el proceso completo de traslado de un jubilado alemán, holandés o británico a la Costa del Sol, Alicante o Mallorca: búsqueda de vivienda, gestoría de visado, traslado de muebles, apertura de cuenta bancaria, médico de cabecera y comunidad de expatriados. Precio del paquete completo: 3.000-8.000€ con alto margen y cliente con alto poder adquisitivo.", riesgos:["El mercado post-Brexit ha reducido el flujo de británicos (ahora necesitan visa): compensado por alemanes y holandeses","Requiere red de proveedores de confianza en cada destino: médicos, abogados, gestores, empresas de mudanza","Marketing en alemán, inglés y holandés necesario: fuera de la zona de confort de una agencia española"], pasos:["Alianza con empresa de mudanzas internacionales como back-end logístico de la mudanza física","Red de gestores y abogados en los destinos principales: Costa del Sol, Alicante, Mallorca, Tenerife","Web en alemán, inglés y holandés con contenido específico de cada destino","Canal: anuncios en revistas y webs de jubilados europeos (German Auswanderer forums, expatica.com, angloinfo.com)"] },

  { id:100, nombre:"Plataforma de Economía Colaborativa entre Vecinos", emoji:"🤝", sector:"Tech", potencial:"Alta", dificultad:"Moderada", resumen:"App hiperlocal donde los vecinos del mismo edificio o barrio comparten, prestan, venden e intercambian objetos, habilidades y tiempo.", por_que:"Nextdoor (EE.UU.) vale 400M$ conectando vecinos. Olio (UK, intercambio de objetos entre vecinos) tiene 7 millones de usuarios. StreetBank (UK) tiene 50.000 comunidades activas. La economía colaborativa vecinal reduce el consumo un 35% y aumenta el sentido de comunidad un 60% (Harvard Social Capital Study 2024).", como_aplicar:"España tiene la mayor densidad de comunidades de propietarios de Europa (11 millones de hogares en comunidades). La cultura española de 'pedir al vecino' es alta pero no existe ninguna plataforma digital que la organice. Una app donde los vecinos publican lo que prestan, lo que regalan, lo que ofrecen (clases de inglés, peluquería casera) y lo que necesitan, con sistema de valoraciones y gamificación, tiene propuesta clara para comunidades de 50-200 vecinos.", riesgos:["Efecto de red muy localizado: necesitas masa crítica en un mismo edificio o radio de 200m, lo que es difícil de escalar","Monetización muy limitada en el modelo gratuito; la publicidad local puede ser intrusiva y dañar la experiencia","Privacidad y seguridad: conectar a desconocidos en el mismo edificio tiene riesgos de privacidad percibidos"], pasos:["Lanzar en 5 edificios de 100+ vecinos en una ciudad elegida con gestión activa inicial del community manager","Funcionalidades básicas: prestamos, regalos, habilidades y anuncios del edificio (sin mensajería privada para evitar problemas)","Monetización: suscripción de 1-2€/mes por hogar o freemium con publicidad de comercios del barrio","Canal: administradores de fincas y presidentes de comunidades como early adopters y promotores"] },
];

